def _colore_visuale_testo(valore):
    try:
        if pd.isna(valore):
            valore = ''
    except Exception:
        pass
    s = str(valore if valore is not None else '').strip().upper()
    if not s:
        return None
    if 'SILVER' in s:
        return ('#DCEBFF', '#0B4F9C')
    if re.search(r'\bU(?:NDER\s*)?12\b|\bU12[A-Z]*\b', s):
        return ('#FFF3BF', '#5F3B00')
    if re.search(r'\bU(?:NDER\s*)?11\b|\bU11[A-Z]*\b', s):
        return ('#FDE2E2', '#A61B1B')
    if 'U11' in s and 'VERDE' in s:
        return ('#DDF5E3', '#146C2E')
    if 'U11' in s and 'BLU' in s:
        return ('#DCEBFF', '#0B4F9C')
    if 'U11' in s and 'ROSS' in s:
        return ('#FDE2E2', '#A61B1B')
    if 'U11' in s and 'BIANC' in s:
        return ('#F3F4F6', '#374151')
    if 'FIPAV' in s:
        return ('#FDE2E2', '#A61B1B')
    if 'UISP' in s:
        return ('#FFF0D6', '#9A4D00')
    return None

def _style_dataframe_colori(df):
    if df is None:
        return df
    def _css(v):
        c = _colore_visuale_testo(v)
        if not c:
            return ''
        bg, fg = c
        return f'background-color:{bg}; color:{fg}; font-weight:600;'
    try:
        return df.style.map(_css)
    except Exception:
        try:
            return df.style.applymap(_css)
        except Exception:
            return df

def _style_dataframe_nostra_societa(df, nomi_squadra=None, colori_squadre=None):
    """Evidenzia le celle delle squadre della società con il loro colore stabile."""
    # In calendario non applicare colori in base alla sola categoria contenuta
    # nel nome (es. qualunque avversaria con "U12"): colora esclusivamente le
    # denominazioni della nostra società passate esplicitamente in nomi_squadra.
    styled = df.style if df is not None else df
    nomi = {' '.join(str(x or '').casefold().split()) for x in (nomi_squadra or []) if str(x or '').strip()}
    if not nomi or df is None:
        return styled
    _mappa = {
        ' '.join(str(k or '').casefold().split()): v
        for k, v in (colori_squadre or {}).items() if str(k or '').strip()
    }
    def _cell_css(v):
        try:
            if pd.isna(v): v = ''
        except Exception:
            pass
        norm = ' '.join(str(v if v is not None else '').casefold().split())
        if norm not in nomi:
            return ''
        bg = _mappa.get(norm) or _colore_squadra_auto(v)
        return f'background-color:{bg};color:#172033;font-weight:800;border-left:5px solid {bg};'
    try:
        return styled.map(_cell_css)
    except Exception:
        try: return styled.applymap(_cell_css)
        except Exception: return styled

_PALETTE_SQUADRE = [
    '#DCEBFF','#DDF5E3','#FDE2E2','#FFF0D6','#EDE9FE','#CCFBF1',
    '#FCE7F3','#E0F2FE','#FEF3C7','#DCFCE7','#FFE4E6','#E2E8F0',
]

def _colore_squadra_auto(nome):
    """Colore ripetibile per categoria/squadra, uguale in tutte le viste."""
    s = normalizza_intestazione_colonna(nome).upper()
    regole = [
        ('SILVER', '#DCEBFF'),
        ('U12', '#FFF3BF'), ('UNDER 12', '#FFF3BF'),
        ('U11', '#FDE2E2'), ('UNDER 11', '#FDE2E2'),
        ('U13', '#DDF5E3'), ('UNDER 13', '#DDF5E3'),
        ('U14', '#EDE9FE'), ('UNDER 14', '#EDE9FE'),
        ('U15', '#FCE7F3'), ('UNDER 15', '#FCE7F3'),
        ('U17', '#CCFBF1'), ('UNDER 17', '#CCFBF1'),
        ('U19', '#FFF0D6'), ('UNDER 19', '#FFF0D6'),
    ]
    for token, colore in regole:
        if token in s:
            return colore
    indice = int(hashlib.md5(s.encode('utf-8')).hexdigest()[:8], 16) % len(_PALETTE_SQUADRE)
    return _PALETTE_SQUADRE[indice]

def _assegna_colori_squadre(nomi_squadre, colori_esistenti=None):
    """Assegna a ogni squadra Monviso/Eurospin un colore stabile e distinto."""
    return {
        nome:_colore_squadra_auto(nome)
        for nome in sorted({str(x).strip() for x in (nomi_squadre or []) if str(x).strip()}, key=str.casefold)
    }

def _nomi_squadre_da_gare(gare):
    nomi=[]
    for gara in (gare or []):
        if not isinstance(gara,dict): continue
        for chiave in ('squadra_casa','squadra_ospite','Casa','Ospite'):
            nome=str(gara.get(chiave,'') or '').strip()
            if nome: nomi.append(nome)
    return nomi

def _solo_squadre_societa(nomi_squadre, nomi_associati=None):
    """Seleziona soltanto le denominazioni Monviso/Eurospin o associate alla società."""
    associati={' '.join(str(x).casefold().split()) for x in (nomi_associati or []) if str(x).strip()}
    risultato=[]
    for nome in (nomi_squadre or []):
        nome=str(nome or '').strip()
        if not nome: continue
        norm=' '.join(nome.casefold().split())
        if 'monviso' in norm or 'eurospin' in norm or norm in associati:
            risultato.append(nome)
    return sorted(set(risultato),key=str.casefold)

def _style_righe_squadre(df, colori_squadre, colonna='Squadra', nomi_societa=None):
    if df is None or df.empty or colonna not in df.columns:
        return df
    propri={' '.join(str(x).casefold().split()) for x in (nomi_societa or []) if str(x).strip()}
    def _row(row):
        _val=row.get(colonna,'')
        try:
            if pd.isna(_val): _val=''
        except Exception: pass
        nome=str(_val if _val is not None else '').strip(); bg=(colori_squadre or {}).get(nome,'')
        if not bg: return ['']*len(row)
        forte='font-weight:800;border-left:5px solid #2563EB;' if ' '.join(nome.casefold().split()) in propri else 'font-weight:600;'
        return [f'background-color:{bg};color:#0B4F9C;{forte}']*len(row)
    try: return df.style.apply(_row,axis=1)
    except Exception: return df

