# MESSAGGI AZIONE
# ============================================================
FEEDBACK_DURATA_SECONDI = 3.0

def imposta_feedback(testo, tipo="success"):
    """Salva un messaggio operativo da mostrare dopo il rerun.

    success = verde, info = azzurro, error = rosso.
    Il messaggio non viene cancellato automaticamente: resta visibile fino
    alla successiva operazione, quindi è garantita una permanenza superiore
    ai 3 secondi richiesti anche in caso di caricamenti lenti.
    """
    tipo = tipo if tipo in {"success", "info", "error"} else "info"
    testo = str(testo)
    st.session_state["feedback_azione"] = {
        "testo": testo,
        "tipo": tipo,
        "ts": datetime.now().timestamp(),
    }
    # Feedback immediato: compare anche prima di eventuali st.rerun().
    # Il banner persistente viene mostrato nuovamente al caricamento successivo.
    try:
        icone = {"success": "🟢", "info": "🔵", "error": "🔴"}
        st.toast(f"{icone.get(tipo, '🔵')} {testo}", icon=icone.get(tipo, "🔵"))
    except Exception:
        pass


def mostra_feedback_azione():
    """Mostra in alto un messaggio grande e chiaramente colorato."""
    fb = st.session_state.get("feedback_azione")
    if not isinstance(fb, dict) or not fb.get("testo"):
        return
    tipo = fb.get("tipo", "info")
    testo = str(fb.get("testo", ""))
    palette = {
        "success": ("#198754", "#e9f7ef", "#146c43"),
        "info": ("#0d6efd", "#eaf3ff", "#084298"),
        "error": ("#dc3545", "#fdecef", "#842029"),
    }
    border, bg, text = palette.get(tipo, palette["info"])
    icon = {"success": "🟢", "info": "🔵", "error": "🔴"}.get(tipo, "🔵")
    elapsed = max(0, int(datetime.now().timestamp() - float(fb.get("ts", datetime.now().timestamp()))))
    st.markdown(
        f'''<div style="margin:8px 0 16px 0;padding:13px 18px;border:2px solid {border};border-radius:9px;background:{bg};color:{text};font-size:16px;font-weight:600;box-shadow:0 2px 6px rgba(0,0,0,.08);">{icon}&nbsp; {testo}<span style="float:right;font-size:11px;font-weight:400;opacity:.65;">{elapsed}s</span></div>''',
        unsafe_allow_html=True,
    )


def registra_storico_crescita(atleta):
    """Registra una fotografia completa della valutazione tecnica corrente.

    Lo storico principale vive nella scheda atleta e viene quindi persistito
    insieme all'anagrafica. Una copia viene mantenuta anche nel file storico
    dedicato per report e compatibilita. Un errore della copia secondaria non
    deve far risultare fallita la registrazione principale.
    """
    try:
        atleta_id = str(atleta.get("id") or "").strip()
        if not atleta_id:
            return False
        v = atleta.get("valutazioni_tecniche", {}) or {}
        now = ora_italiana()
        voce = {
            "id": uuid.uuid4().hex,
            "data": now.strftime("%d/%m/%Y"),
            "ora": now.strftime("%H:%M:%S"),
            "timestamp": now.isoformat(timespec="seconds"),
            "stagione": str(atleta.get("stagione", "")),
            "operatore": str(st.session_state.get("username_corrente", "admin")),
            "ruolo": v.get("ruolo", ""), "altezza": v.get("altezza", ""),
            "salto_attacco": v.get("salto_attacco", ""), "peso": v.get("peso", ""),
            "battuta": v.get("battuta", ""), "attacco": v.get("attacco", ""),
            "ricezione": v.get("ricezione", ""), "palleggio": v.get("palleggio", ""),
            "muro": v.get("muro", ""), "difesa": v.get("difesa", ""),
            "forza": v.get("forza", ""), "velocita": v.get("velocita", ""),
            "coordinazione": v.get("coordinazione", ""), "tecnica": v.get("tecnica", ""),
            "tattica": v.get("tattica", ""), "mentalita": v.get("mentalita", ""),
            "crescita": v.get("crescita", ""),
        }

        # Registro principale: direttamente nella scheda atleta.
        elenco_atleta = atleta.get("storico_crescita_tecnica", [])
        if not isinstance(elenco_atleta, list):
            elenco_atleta = []
        elenco_atleta.append(voce)
        atleta["storico_crescita_tecnica"] = elenco_atleta

        # Copia separata per report/compatibilita.
        storico = st.session_state.get("storico_tecnico", {})
        if not isinstance(storico, dict):
            storico = {}
        elenco_file = storico.get(atleta_id, [])
        if not isinstance(elenco_file, list):
            elenco_file = []
        elenco_file.append(dict(voce))
        storico[atleta_id] = elenco_file
        st.session_state["storico_tecnico"] = storico
        try:
            salva_json_sicuro(FILE_STORICO_TECNICO, storico)
        except Exception:
            pass
        return True
    except Exception:
        return False

def storico_crescita_atleta(atleta):
    """Restituisce lo storico completo dell'atleta, dal record atleta o archivio."""
    storico_atleta = atleta.get("storico_crescita_tecnica", [])
    if isinstance(storico_atleta, list) and storico_atleta:
        return storico_atleta

    storico = st.session_state.get("storico_tecnico", {})
    atleta_id = str(atleta.get("id") or "").strip()
    if isinstance(storico, dict) and atleta_id in storico and isinstance(storico[atleta_id], list):
        return storico[atleta_id]

    nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().lower()
    if isinstance(storico, dict):
        for key, value in storico.items():
            if str(key).strip().lower() == nome and isinstance(value, list):
                return value
    return []


def _storico_tecnico_fingerprint(record):
    """Identifica una valutazione evitando duplicati tra scheda e archivio separato."""
    if not isinstance(record, dict):
        return ""
    if str(record.get("id", "")).strip():
        return "id:" + str(record.get("id")).strip()
    campi = (
        "timestamp", "data", "ora", "stagione", "operatore", "ruolo", "altezza",
        "salto_attacco", "peso", "battuta", "attacco", "ricezione", "palleggio",
        "muro", "difesa", "forza", "velocita", "coordinazione", "tecnica",
        "tattica", "mentalita", "crescita",
    )
    payload = json.dumps([record.get(k, "") for k in campi], ensure_ascii=False, default=str)
    return "sha:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _unisci_storici_tecnici(*elenchi):
    risultato, visti = [], set()
    for elenco in elenchi:
        if not isinstance(elenco, list):
            continue
        for voce in elenco:
            if not isinstance(voce, dict):
                continue
            fp = _storico_tecnico_fingerprint(voce)
            if fp and fp not in visti:
                visti.add(fp)
                risultato.append(dict(voce))
    return sorted(
        risultato,
        key=lambda x: str(x.get("timestamp", f"{x.get('data','')} {x.get('ora','')}")),
    )


def _chiavi_identita_atleta(atleta):
    chiavi = []
    atleta_id = str(atleta.get("id", "")).strip().casefold()
    sync_key = str(atleta.get("sync_key", "")).strip().casefold()
    cf = re.sub(r"\s+", "", str(atleta.get("cf", ""))).casefold()
    nome = " ".join(
        x for x in [str(atleta.get("cognome", "")).strip(), str(atleta.get("nome", "")).strip()] if x
    ).casefold()
    nascita = str(atleta.get("data_nas", "")).strip().casefold()
    stagione = str(atleta.get("stagione", "")).strip().casefold()
    if atleta_id: chiavi.append("id:" + atleta_id)
    if sync_key: chiavi.append("sync:" + sync_key)
    # La stessa atleta puo avere una scheda per ogni stagione: prima tenta
    # sempre l'abbinamento stagionale, poi usa le chiavi generali di fallback.
    if cf and stagione: chiavi.append("cf_stagione:" + cf + "|" + stagione)
    if nome and nascita and stagione: chiavi.append("persona_stagione:" + nome + "|" + nascita + "|" + stagione)
    if nome and stagione: chiavi.append("nome_stagione:" + nome + "|" + stagione)
    if cf: chiavi.append("cf:" + cf)
    if nome and nascita: chiavi.append("persona:" + nome + "|" + nascita)
    if nome: chiavi.append("nome:" + nome)
    return chiavi


def riconcilia_storico_crescita(atlete, storico_separato):
    """Unisce le due copie dello storico e le riallinea senza cancellare record."""
    if not isinstance(atlete, list):
        atlete = []
    if not isinstance(storico_separato, dict):
        storico_separato = {}
    indice = {}
    for atleta in atlete:
        if not isinstance(atleta, dict):
            continue
        for chiave in _chiavi_identita_atleta(atleta):
            indice.setdefault(chiave, atleta)
    # Collega anche i vecchi archivi indicizzati direttamente per nome o per ID.
    for vecchia_chiave, elenco in list(storico_separato.items()):
        k = str(vecchia_chiave or "").strip().casefold()
        atleta = indice.get("id:" + k) or indice.get("nome:" + k)
        if atleta is not None:
            atleta["storico_crescita_tecnica"] = _unisci_storici_tecnici(
                atleta.get("storico_crescita_tecnica", []), elenco
            )
    nuovo_storico = {}
    for atleta in atlete:
        if not isinstance(atleta, dict):
            continue
        atleta_id = str(atleta.get("id", "")).strip()
        if not atleta_id:
            continue
        unito = _unisci_storici_tecnici(
            atleta.get("storico_crescita_tecnica", []), storico_separato.get(atleta_id, [])
        )
        if unito:
            atleta["storico_crescita_tecnica"] = unito
            nuovo_storico[atleta_id] = [dict(x) for x in unito]
    # Conserva eventuali record non ancora associabili, per non perderli.
    for chiave, elenco in storico_separato.items():
        if str(chiave) not in nuovo_storico and isinstance(elenco, list) and elenco:
            nuovo_storico[str(chiave)] = _unisci_storici_tecnici(elenco)
    return atlete, nuovo_storico

