def hash_password(password):
    salt = secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt), PASSWORD_ITERATIONS)
    return f"pbkdf2_sha256${PASSWORD_ITERATIONS}${salt}${digest.hex()}"


def verifica_password(password, stored):
    if not stored:
        return False
    if not str(stored).startswith("pbkdf2_sha256$"):
        return hmac.compare_digest(str(password), str(stored))
    try:
        _, iterations, salt, expected = str(stored).split("$", 3)
        actual = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt), int(iterations)).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False


def password_valida(password):
    return (
        len(password) >= 10
        and any(c.isupper() for c in password)
        and any(c.islower() for c in password)
        and any(c.isdigit() for c in password)
    )


def _sicurezza_login_stato(username):
    username = str(username or "").strip().casefold() or "__vuoto__"
    archivio = st.session_state.setdefault("_sicurezza_tentativi_login", {})
    record = archivio.get(username, {}) if isinstance(archivio, dict) else {}
    try:
        bloccato_fino = datetime.fromisoformat(str(record.get("bloccato_fino", "")))
    except Exception:
        bloccato_fino = None
    ora = ora_italiana().replace(tzinfo=None)
    if bloccato_fino and ora < bloccato_fino:
        minuti = max(1, int(((bloccato_fino - ora).total_seconds() + 59) // 60))
        return True, minuti, int(record.get("tentativi", 0) or 0)
    if bloccato_fino:
        archivio.pop(username, None)
    return False, 0, int(record.get("tentativi", 0) or 0)


def _sicurezza_login_fallito(username):
    username = str(username or "").strip().casefold() or "__vuoto__"
    archivio = st.session_state.setdefault("_sicurezza_tentativi_login", {})
    record = archivio.setdefault(username, {"tentativi": 0})
    record["tentativi"] = int(record.get("tentativi", 0) or 0) + 1
    if record["tentativi"] >= LOGIN_MAX_TENTATIVI:
        record["bloccato_fino"] = (
            ora_italiana().replace(tzinfo=None) + timedelta(minutes=LOGIN_BLOCCO_MINUTI)
        ).isoformat(timespec="seconds")
        return True, LOGIN_BLOCCO_MINUTI, 0
    return False, 0, LOGIN_MAX_TENTATIVI - record["tentativi"]


def _sicurezza_login_riuscito(username):
    archivio = st.session_state.setdefault("_sicurezza_tentativi_login", {})
    archivio.pop(str(username or "").strip().casefold() or "__vuoto__", None)
    st.session_state["_sessione_ultima_attivita"] = ora_italiana().replace(tzinfo=None).isoformat(timespec="seconds")


def _sicurezza_verifica_timeout_sessione():
    if not st.session_state.get("utente_autenticato"):
        return False
    ora = ora_italiana().replace(tzinfo=None)
    try:
        ultima = datetime.fromisoformat(str(st.session_state.get("_sessione_ultima_attivita", ""))).replace(tzinfo=None)
    except Exception:
        ultima = ora
    if (ora - ultima).total_seconds() > SESSIONE_TIMEOUT_MINUTI * 60:
        for chiave in ("utente_autenticato", "username_corrente", "ruolo_corrente", "area_corrente", "_sessione_ultima_attivita"):
            st.session_state.pop(chiave, None)
        st.session_state["utente_autenticato"] = False
        st.session_state["_sessione_scaduta_avviso"] = True
        return True
    st.session_state["_sessione_ultima_attivita"] = ora.isoformat(timespec="seconds")
    return False


def _sicurezza_logout():
    for chiave in ("username_corrente", "ruolo_corrente", "area_corrente", "_sessione_ultima_attivita", "_login_2fa"):
        st.session_state.pop(chiave, None)
    st.session_state["utente_autenticato"] = False


def _2fa_hash_codice(codice):
    return hashlib.sha256(str(codice or "").strip().upper().encode("utf-8")).hexdigest()


def _2fa_email_mascherata(email):
    email = str(email or "").strip()
    if "@" not in email:
        return "indirizzo non configurato"
    nome, dominio = email.split("@", 1)
    visibile = nome[:2] if len(nome) > 1 else nome[:1]
    return f"{visibile}{'*' * max(3, len(nome) - len(visibile))}@{dominio}"


def _2fa_genera_codici_recupero(numero=8):
    alfabeto = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    codici = []
    for _ in range(numero):
        grezzo = "".join(secrets.choice(alfabeto) for _ in range(10))
        codici.append(f"{grezzo[:5]}-{grezzo[5:]}")
    return codici


def _2fa_invia_codice(username, email, reinvio=False):
    ora = ora_italiana()
    stato = st.session_state.get("_login_2fa", {})
    if reinvio and stato:
        try:
            ultimo = datetime.fromisoformat(str(stato.get("inviato_il", "")))
            restano = OTP_REINVIO_SECONDI - int((ora - ultimo).total_seconds())
        except Exception:
            restano = 0
        if restano > 0:
            return False, f"Attendi ancora {restano} secondi prima di richiedere un nuovo codice."
    codice = f"{secrets.randbelow(1_000_000):06d}"
    oggetto = f"Codice di accesso Gestionale {nome_societa}" if 'nome_societa' in globals() else "Codice di accesso Gestionale Volley"
    testo = (
        f"Il tuo codice monouso e: {codice}\n\n"
        f"Il codice e valido per {OTP_VALIDITA_MINUTI} minuti e puo essere usato una sola volta.\n"
        "Se non hai richiesto tu l'accesso, ignora questa email e informa la societa."
    )
    ok, errore = invia_email_automatica(email, oggetto, testo)
    if not ok:
        return False, f"Invio del codice non riuscito: {errore}"
    st.session_state["_login_2fa"] = {
        "username": str(username), "email": str(email),
        "codice_hash": _2fa_hash_codice(codice),
        "scade_il": (ora + timedelta(minutes=OTP_VALIDITA_MINUTI)).isoformat(timespec="seconds"),
        "inviato_il": ora.isoformat(timespec="seconds"), "tentativi": 0,
    }
    return True, ""


def _completa_accesso_utente(username, record):
    _sicurezza_login_riuscito(username)
    st.session_state.pop("_login_2fa", None)
    st.session_state["utente_autenticato"] = True
    st.session_state["username_corrente"] = username
    st.session_state["ruolo_corrente"] = record.get("ruolo", "")
    raw_area = record.get("area", ["Area Amministratori"])
    st.session_state["area_corrente"] = raw_area if isinstance(raw_area, list) else [raw_area]


@st.cache_data(show_spinner=False)
def _carica_json_cached(file, mtime_ns, default):
    if os.path.exists(file):
        try:
            with open(file, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return default


def carica_json(file, default):
    try:
        mtime_ns = os.stat(file).st_mtime_ns if os.path.exists(file) else 0
    except OSError:
        mtime_ns = 0
    return _carica_json_cached(file, mtime_ns, default)


def esegui_backup(file=None, retention=20):
    os.makedirs(CARTELLA_BACKUP, exist_ok=True)
    files = [file] if file else [
        FILE_UTENTI, FILE_GRUPPI, FILE_CATEGORIE, FILE_ATLETE, FILE_CONFIG_QUOTE,
        FILE_BUDGET, FILE_SQUADRE, FILE_ALLENAMENTI, FILE_PRESENZE_PROMO, FILE_GARE, FILE_STORICO_TECNICO, FILE_SCOUT, FILE_CONFIG_VOCI_SCOUT,
        FILE_CONFIG_SOCIETA, FILE_CONFIG_VOCI_COSTI, FILE_CONFIG_COSTI_STANDARD,
        FILE_CONFIG_NOTIFICHE, FILE_LOG_NOTIFICHE, FILE_ATLETE_ELIMINATE_SYNC,
        FILE_CATEGORIE_GRUPPI, FILE_CATEGORIE_COSTI, FILE_PRIMA_NOTA, FILE_RICEVUTE, FILE_FIPAV_ATTIVITA, FILE_ARCHIVIO_FEDERALE, FILE_STAFF_SOCIETA, FILE_ORGANIGRAMMA_STAFF,
        FILE_ABBIGLIAMENTO_CONSEGNE, FILE_ABBIGLIAMENTO_CONFIG,
        FILE_MAG_ARTICOLI, FILE_MAG_MOVIMENTI, FILE_MAG_CONSEGNE,
        FILE_MAG_INVENTARI, FILE_MAG_CATEGORIE,
    ]
    data_oggi = ora_italiana().strftime("%Y%m%d_%H%M%S_%f")
    for sorgente in files:
        if not sorgente or not os.path.exists(sorgente):
            continue
        try:
            base = os.path.basename(sorgente)
            shutil.copy2(sorgente, os.path.join(CARTELLA_BACKUP, f"{base}_{data_oggi}.bak"))
            backups = sorted(
                Path(CARTELLA_BACKUP).glob(f"{base}_*.bak"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            for vecchio in backups[retention:]:
                vecchio.unlink(missing_ok=True)
        except OSError:
            pass


def _elenco_file_backup():
    """Elenco unico degli archivi inclusi nei backup e ammessi al ripristino."""
    files = [
        FILE_UTENTI, FILE_GRUPPI, FILE_CATEGORIE, FILE_CATEGORIE_GRUPPI, FILE_ATLETE,
        FILE_CONFIG_QUOTE, FILE_BUDGET, FILE_SQUADRE, FILE_ALLENAMENTI,
        FILE_PRESENZE_PROMO, FILE_GARE, FILE_STORICO_TECNICO, FILE_SCOUT,
        FILE_CONFIG_VOCI_SCOUT, FILE_CONFIG_SOCIETA, FILE_CONFIG_VOCI_COSTI,
        FILE_CONFIG_COSTI_STANDARD, FILE_CONFIG_NOTIFICHE, FILE_LOG_NOTIFICHE,
        FILE_ATLETE_ELIMINATE_SYNC, FILE_CATEGORIE_COSTI, FILE_PRIMA_NOTA,
        FILE_RICEVUTE, FILE_FIPAV_ATTIVITA, FILE_ARCHIVIO_FEDERALE,
        FILE_STAFF_SOCIETA, FILE_ORGANIGRAMMA_STAFF, FILE_UISP_MAPPING, FILE_CAL_SYNC,
        FILE_CAMPIONATI_ESTERNI, FILE_REGISTRO_ATTIVITA,
        FILE_RUBRICA_CONTATTI,
        FILE_ABBIGLIAMENTO_CONSEGNE, FILE_ABBIGLIAMENTO_CONFIG,
        FILE_MAG_ARTICOLI, FILE_MAG_MOVIMENTI, FILE_MAG_CONSEGNE,
        FILE_MAG_INVENTARI, FILE_MAG_CATEGORIE,
    ]
    # Mantiene l'ordine ed evita duplicati accidentali.
    return list(dict.fromkeys(str(x) for x in files if x))


def crea_backup_zip(include_allegati=False):
    """Crea un backup scaricabile dal browser. Include tutti i JSON dell'app.
    Su ambienti cloud il filesystem locale non è da considerare archivio definitivo;
    il download ZIP consente di conservare una copia esterna affidabile.
    """
    files_backup = _elenco_file_backup()
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
        for nome in files_backup:
            p = Path(nome)
            if p.exists() and p.is_file():
                p_norm = str(p).replace("\\", "/")
                arcname = p_norm if p_norm.startswith("magazzino/data/") else f"dati/{p.name}"
                zf.write(p, arcname=arcname)
        if include_allegati:
            base = Path(CARTELLA_ALLEGATI)
            if base.exists():
                for p in base.rglob('*'):
                    if p.is_file():
                        try:
                            zf.write(p, arcname=str(Path('allegati') / p.relative_to(base)))
                        except OSError:
                            pass
        manifest = {
            'creato_il': ora_italiana().strftime('%Y-%m-%d %H:%M:%S'),
            'stagione': str(st.session_state.get('stagione_selezionata', '')),
            'include_allegati': bool(include_allegati),
            'nota': 'Backup generato dal Gestionale Volley configurabile.'
        }
        zf.writestr('MANIFEST.json', json.dumps(manifest, ensure_ascii=False, indent=2))
    buffer.seek(0)
    return buffer.getvalue()


