    """Ricevuta dinamica: non contiene piu dati fiscali di un'altra societa."""
    buffer = io.BytesIO()
    p = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    data_odierna = ora_italiana().strftime("%d/%m/%Y")
    stagione = atleta.get("stagione", "2026/2027")
    cognome_nome = f"{atleta.get('cognome', '')} {atleta.get('nome', '')}".strip().upper()
    p.setFont("Helvetica-Bold", 14)
    p.drawString(50, height - 42, "RICEVUTA DI PAGAMENTO")
    p.setFont("Helvetica", 9)
    p.drawString(50, height - 58, str(societa or "Societa sportiva"))
    y = height - 90
    societa_details = []
    if config_societa.get("rappresentante"):
        societa_details.append(f"Legale rappresentante: {config_societa['rappresentante']}")
    if config_societa.get("sede"):
        societa_details.append(f"Sede: {config_societa['sede']}")
    if config_societa.get("piva_cf"):
        societa_details.append(f"P. IVA / C.F.: {config_societa['piva_cf']}")
    if config_societa.get("cod_fipav"):
        societa_details.append(f"Cod. FIPAV: {config_societa['cod_fipav']}")
    if config_societa.get("numero_coni"):
        societa_details.append(f"Registro/CONI: {config_societa['numero_coni']}")
    if not societa_details:
        societa_details.append("Dati societari completi configurabili dall'area amministratori.")
    p.setFont("Helvetica", 8)
    for line in societa_details:
        p.drawString(50, y, line[:120])
        y -= 12
    y -= 8
    p.setFont("Helvetica", 9)
    attest = (
        f"Si attesta di aver ricevuto in data {data_odierna} la somma di Euro {safe_float(importo):,.2f} "
        f"per quota associativa e partecipazione all'attivita sportiva della stagione {stagione}."
    )
    for line in _wrap_text(attest, 105):
        p.drawString(50, y, line)
        y -= 12
    y -= 8
    p.setFont("Helvetica-Bold", 10)
    p.drawString(50, y, f"ATLETA: {cognome_nome}")
    y -= 16
    p.setFont("Helvetica", 9)
    p.drawString(50, y, f"Data di nascita: {atleta.get('data_nas', '-')}")
    y -= 13
    p.drawString(50, y, f"Codice fiscale: {atleta.get('cf', '-')}")
    y -= 22
    p.setFont("Helvetica", 8)
    nota = "La ricevuta puo essere completata con i riferimenti fiscali configurati dalla societa, ove necessari."
    for line in _wrap_text(nota, 105):
        p.drawString(50, y, line)
        y -= 11
    y -= 25
    p.setFont("Helvetica", 9)
    citta = config_societa.get("citta_ricevuta") or ""
    luogo = f"{citta}, " if citta else ""
    p.drawString(50, y, f"In fede. {luogo}{data_odierna}")
    p.drawString(350, y, str(societa or "Societa sportiva")[:38])
    p.setFont("Helvetica", 8.5)
    if config_societa.get("rappresentante"):
        p.drawString(350, y - 15, "Legale rappresentante")
        p.drawString(350, y - 30, str(config_societa.get("rappresentante"))[:38])
    p.showPage()
    p.save()
    buffer.seek(0)
    return buffer.getvalue()
