def prossimo_numero_ricevuta(stagione, ricevute=None):
    ricevute = ricevute if isinstance(ricevute, list) else st.session_state.get("ricevute", [])
    prefisso = str(stagione or "").replace("/", "-")
    massimo = 0
    for r in ricevute:
        if str(r.get("stagione", "")) != str(stagione or ""):
            continue
        numero = str(r.get("numero", ""))
        try:
            massimo = max(massimo, int(numero.rsplit("/", 1)[-1]))
        except Exception:
            pass
    return f"{prefisso}/{massimo + 1:04d}"

def prossimo_numero_certificazione(anno, ricevute=None):
    ricevute = ricevute if isinstance(ricevute, list) else st.session_state.get("ricevute", [])
    prefisso = f"CERT-{int(anno)}"
    massimo = 0
    for r in ricevute:
        numero = str(r.get("numero", ""))
        if not numero.startswith(prefisso + "/"):
            continue
        try:
            massimo = max(massimo, int(numero.rsplit("/", 1)[-1]))
        except Exception:
            pass
    return f"{prefisso}/{massimo + 1:04d}"


def _importo_lettere_it(valore):
    """Importo in lettere, sufficiente per le normali quote sportive."""
    n = int(abs(safe_float(valore)))
    cent = int(round((abs(safe_float(valore)) - n) * 100))
    if cent == 100:
        n += 1; cent = 0
    unita = ["zero","uno","due","tre","quattro","cinque","sei","sette","otto","nove","dieci","undici","dodici","tredici","quattordici","quindici","sedici","diciassette","diciotto","diciannove"]
    decine = ["","","venti","trenta","quaranta","cinquanta","sessanta","settanta","ottanta","novanta"]
    def sotto_mille(x):
        if x < 20: return unita[x]
        if x < 100:
            d, u = divmod(x,10); base=decine[d]
            if u in (1,8): base=base[:-1]
            return base + (unita[u] if u else "")
        c, r = divmod(x,100); base = "cento" if c==1 else unita[c]+"cento"
        if 80 <= r < 90: base=base[:-1]
        return base + (sotto_mille(r) if r else "")
    if n < 1000: testo=sotto_mille(n)
    elif n < 1000000:
        m, r=divmod(n,1000); testo=("mille" if m==1 else sotto_mille(m)+"mila") + (sotto_mille(r) if r else "")
    else:
        testo=str(n)
    return f"{testo.capitalize()}/{cent:02d}"


PINEROLO_LOGO_B64 = ""

def _pinerolo_logo_reader():
    # Nella versione Master non viene applicato alcun logo incorporato:
    # ricevute e certificazioni usano esclusivamente il logo configurato.
    return None

def _firma_presidente_reader(cfg=None):
    """Restituisce la firma grafica configurata, se presente."""
    dati_cfg=cfg if isinstance(cfg,dict) else {}
    valore=str(dati_cfg.get('firma_presidente_b64','') or config_societa.get('firma_presidente_b64','') or '')
    if not valore:
        return None
    try:
        return ImageReader(io.BytesIO(base64.b64decode(valore)))
    except Exception:
        return None

def _normalizza_firma_png_b64(dati):
    """Converte JPEG/PNG in un PNG compatto, orientato e con il bianco trasparente."""
    raw=bytes(dati or b'')
    if not raw:
        raise ValueError('Il file della firma è vuoto.')
    if len(raw)>2*1024*1024:
        raise ValueError('La firma supera 2 MB. Usa un’immagine più leggera.')
    try:
        img=ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert('RGBA')
    except Exception as exc:
        raise ValueError(f'Immagine firma non leggibile: {exc}')
    img.thumbnail((1400,500),Image.Resampling.LANCZOS)
    pixel=[]
    for r,g,b,a in img.getdata():
        # I JPEG non hanno trasparenza: rendiamo trasparente lo sfondo quasi bianco.
        if r>=245 and g>=245 and b>=245:
            pixel.append((255,255,255,0))
        else:
            pixel.append((r,g,b,a))
    img.putdata(pixel)
    alpha=img.getchannel('A'); bbox=alpha.getbbox()
    if bbox:
        img=img.crop(bbox)
    out=io.BytesIO(); img.save(out,format='PNG',optimize=True)
    return base64.b64encode(out.getvalue()).decode('ascii')

def _dati_societa_ricevuta(ricevuta):
    # Le ricevute nuove conservano uno snapshot: modifiche future alla configurazione
    # non alterano i documenti gia emessi. Le vecchie usano la configurazione corrente.
    snap = ricevuta.get("societa_snapshot") if isinstance(ricevuta, dict) else None
    if isinstance(snap, dict) and snap:
        # Le ricevute emesse prima dell'introduzione dei dati completi del legale
        # rappresentante contengono snapshot parziali: integriamo SOLO i campi
        # mancanti con i dati ufficiali configurati. Gli snapshot completi restano immutabili.
        dati = dict(snap)
        for _k in DEFAULT_DATI_RICEVUTE:
            if not str(dati.get(_k, "") or "").strip():
                dati[_k] = config_societa.get(_k, DEFAULT_DATI_RICEVUTE[_k])
        return dati
    return dict(config_societa)

def genera_pdf_ricevuta_v2(ricevuta, atleta, societa):
    """Ricevuta formale A4: wrapping per parole intere e impaginazione stabile."""
    buffer = io.BytesIO()
    p = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    sx, dx = 50, width - 50
    usable_w = dx - sx
    cfg = _dati_societa_ricevuta(ricevuta)

    def draw_wrapped(text, x, y, font="Times-Roman", size=11, leading=15, max_width=None):
        """Disegna testo senza spezzare mai le parole a meta'."""
        max_width = max_width or usable_w
        p.setFont(font, size)
        words = str(text or "").split()
        if not words:
            return y
        line = words[0]
        for word in words[1:]:
            candidate = line + " " + word
            if pdfmetrics.stringWidth(candidate, font, size) <= max_width:
                line = candidate
            else:
                p.drawString(x, y, line)
                y -= leading
                line = word
        p.drawString(x, y, line)
        return y - leading

    # Doppio logo.
    pin_logo = _pinerolo_logo_reader()
    if pin_logo:
        try:
            p.drawImage(pin_logo, sx, height-126, width=86, height=86,
                        preserveAspectRatio=True, anchor='c', mask='auto')
        except Exception:
            pass
    monviso_logo = logo_societa_path()
    if monviso_logo:
        try:
            p.drawImage(ImageReader(monviso_logo), dx-86, height-120, width=86, height=74,
                        preserveAspectRatio=True, anchor='c', mask='auto')
        except Exception:
            pass

    tipo = str(ricevuta.get("tipo", "Ricevuta / quietanza (non fiscale)"))
    fiscale = tipo.startswith("Fiscale")
    detraibile = bool(ricevuta.get('detraibile',True))
    p.setFont("Times-Bold", 18)
    p.drawCentredString(width/2, height-62,
                        ("RICEVUTA DI PAGAMENTO" if detraibile else "QUIETANZA DI PAGAMENTO") if not fiscale else "BOZZA DATI DOCUMENTO FISCALE")
    p.setFont("Times-Bold", 11)
    p.drawCentredString(width/2, height-84,
                        ("Ai sensi e per gli effetti dell'art. 1, c. 319 L. n. 296 del 27.12.2006" if detraibile else "SINGOLO PAGAMENTO - DOCUMENTO NON DETRAIBILE"))
    p.setFont("Helvetica", 9)
    p.drawCentredString(width/2, height-103,
                        f"N. {ricevuta.get('numero','-')}  -  Emessa il {ricevuta.get('data_emissione','-')}")

    y = height - 174
    rapp = str(cfg.get('rappresentante','') or '').strip()
    luogo_r = str(cfg.get('rappresentante_luogo_nascita','') or '').strip()
    data_r = str(cfg.get('rappresentante_data_nascita','') or '').strip()
    denom = str(cfg.get('denominazione_ricevute','') or cfg.get('nome','') or societa or 'Societa sportiva').strip()
    sede = str(cfg.get('sede','') or '').strip()
    fipav = str(cfg.get('cod_fipav','') or '').strip()
    coni = str(cfg.get('numero_coni','') or '').strip()
    piva = str(cfg.get('piva_cf','') or '').strip()

    intro = f"Il sottoscritto {rapp or '-'}"
    if luogo_r: intro += f", nato a {luogo_r}"
    if data_r: intro += f" il {data_r}"
    intro += f", in qualita di presidente e legale rappresentante della {denom}"
    if fipav: intro += f" - cod. Fipav {fipav}"
    if coni: intro += f" - N. registrazione CONI {coni}"
    if sede: intro += f", con sede in {sede}"
    if piva: intro += f" - P. IVA/C.F. {piva}"
    y = draw_wrapped(intro, sx, y, "Times-Roman", 10.7, 15)

    y -= 9
    p.setFont("Times-Bold", 14)
    p.drawCentredString(width/2, y, "ATTESTA")
    y -= 25

    importo = safe_float(ricevuta.get('importo',0))
    imp_it = f"{importo:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
    stagione = str(ricevuta.get('stagione','-')).replace('-', '/')
    testo = (f"di aver ricevuto in data {ricevuta.get('data_pagamento','-')} la somma di Euro {imp_it} "
             f"({_importo_lettere_it(importo)}) per la quota associativa e di partecipazione all'attivita sportiva "
             f"di {ricevuta.get('attivita_sportiva','Pallavolo')} svolta nella stagione sportiva {stagione} "
             f"dall'associata/o")
    y = draw_wrapped(testo, sx, y, "Times-Roman", 10.7, 15)

    y -= 7
    nome_atl = str(ricevuta.get('atleta_nome','-') or '-').upper()
    nascita = str(atleta.get('data_nas','') or '').strip()
    luogo_nas = " ".join(x for x in [str(atleta.get('luogo_nas','') or '').strip(),
                                      str(atleta.get('prov_nas','') or '').strip()] if x)
    p.setFont("Times-Bold", 10.8)
    p.drawString(sx, y, f"COGNOME E NOME   {nome_atl}")
    y -= 17
    p.setFont("Times-Roman", 10.7)
    if nascita or luogo_nas:
        p.drawString(sx, y, f"LUOGO E DATA DI NASCITA   {luogo_nas}{', ' if luogo_nas and nascita else ''}{nascita}")
        y -= 17
    p.drawString(sx, y, f"CODICE FISCALE   {ricevuta.get('atleta_cf','-') or '-'}")
    y -= 22

    pagatore = str(ricevuta.get('pagatore_nome','') or '').strip()
    pagcf = str(ricevuta.get('pagatore_cf','') or '').strip()
    if pagatore:
        y = draw_wrapped(f"Pagamento effettuato da: {pagatore} - C.F. {pagcf or '-'}",
                         sx, y, "Times-Roman", 10.3, 14)
    y = draw_wrapped(f"Metodo di pagamento: {ricevuta.get('metodo','-')}   -   Causale: {ricevuta.get('causale','-')}",
                     sx, y, "Times-Roman", 10.3, 14)
    y -= 6

    if ricevuta.get("bollo_applicato"):
        p.setFont("Times-Bold", 9.5)
        p.drawString(sx, y, "Marca da bollo Euro 2,00 applicata")
        y -= 17

    if cfg.get('dicitura_detrazione_ricevute', True) and not fiscale and ricevuta.get('detraibile',True):
        nota = ("La presente attestazione viene rilasciata anche ai fini della detrazione IRPEF prevista dall'art. 15, c. 1, "
                "lett. i-quinquies, D.P.R. 917/1986 e relativo decreto di attuazione, qualora spettante.")
        y = draw_wrapped(nota, sx, y, "Times-Roman", 9.4, 13)
    elif fiscale:
        y = draw_wrapped("BOZZA / PRO-MEMORIA: questo PDF non e una fattura elettronica e non viene trasmesso allo SDI.",
                         sx, y, "Times-Bold", 9, 12)
    elif not ricevuta.get('detraibile',True):
        y = draw_wrapped("Quietanza del singolo pagamento. Documento non utilizzabile ai fini della detrazione IRPEF: sara sostituito dalla certificazione cumulativa del periodo.",
                         sx, y, "Times-Bold", 9, 12)

    if ricevuta.get('note'):
        y -= 3
        y = draw_wrapped("Note: " + str(ricevuta.get('note')), sx, y, "Times-Roman", 9, 12)

    # Chiusura: posizione minima per lasciare respiro e firma ben separata.
    y = min(y - 12, 205)
    p.setFont("Times-Roman", 11)
    p.drawString(sx, y, "In fede.")
    y -= 34
    luogo = str(cfg.get("citta_ricevuta", "") or "").strip()
    p.drawString(sx, y, f"{luogo}, {ricevuta.get('data_emissione','')}")

    firma_x = 330
    firma_c = (firma_x + dx) / 2
    p.setFont("Times-Bold", 10.7)
    p.drawCentredString(firma_c, y, denom[:52])
    p.setFont("Times-Roman", 10.3)
    p.drawCentredString(firma_c, y-17, f"Il Presidente {rapp}".strip())
    firma_img=_firma_presidente_reader(cfg)
    if firma_img:
        try: p.drawImage(firma_img,firma_x+30,y-67,width=125,height=42,preserveAspectRatio=True,anchor='c',mask='auto')
        except Exception: pass
    p.line(firma_x, y-70, dx, y-70)

    p.showPage()
    p.save()
    buffer.seek(0)
    return buffer.getvalue()

def genera_pdf_certificazione_cumulativa(ricevuta, atleta, societa, bozza=False):
    """Certificazione cumulativa delle quote sportive pagate in un periodo dell'anno solare."""
    buffer=io.BytesIO(); p=canvas.Canvas(buffer,pagesize=A4)
