    tw,th=tab.wrapOn(p,dx-sx,y-170); tab.drawOn(p,sx,y-th); y-=th+18
    p.setFont('Times-Bold',11); p.drawRightString(dx,y,f"TOTALE: Euro {imp}"); y-=22
