    if bozza:
        p.saveState(); p.setFillColor(colors.Color(0.8,0.1,0.1,alpha=0.16)); p.setFont('Helvetica-Bold',54); p.translate(width/2,height/2); p.rotate(35); p.drawCentredString(0,0,'BOZZA'); p.restoreState()
    y=min(y-15,175); p.setFont('Times-Roman',10.5); p.drawString(sx,y,'In fede.')
