def normalizza_movimento_prima_nota(movimento):
    """Rende compatibili eventuali record vecchi/incompleti senza perdere dati."""
    m = dict(movimento or {})
    m.setdefault("id", uuid.uuid4().hex)
    m["stagione"] = str(m.get("stagione", "") or "").strip()
    m["tipo"] = str(m.get("tipo", "USCITA") or "USCITA").strip().upper()
    if m["tipo"] not in {"ENTRATA", "USCITA"}:
        m["tipo"] = "USCITA"
    m["categoria"] = str(m.get("categoria", "ALTRO") or "ALTRO").strip().upper()
    m["descrizione"] = str(m.get("descrizione", "") or "").strip()
    m["importo"] = round(max(0.0, safe_float(m.get("importo", 0))), 2)
    m["metodo_pagamento"] = str(m.get("metodo_pagamento", "") or "").strip()
    m["soggetto"] = str(m.get("soggetto", "") or "").strip()
    m["gruppo"] = str(m.get("gruppo", "") or "").strip()
    m["documento"] = str(m.get("documento", "") or "").strip()
    m["note"] = str(m.get("note", "") or "").strip()
    m["origine"] = str(m.get("origine", "MANUALE") or "MANUALE").strip().upper()
    m["origine_id"] = str(m.get("origine_id", "") or "").strip()
    data_txt = str(m.get("data", "") or "").strip()
    if not data_txt:
        data_txt = ora_italiana().strftime("%d/%m/%Y")
    m["data"] = data_txt
    m.setdefault("timestamp", ora_italiana().isoformat(timespec="seconds"))
    m.setdefault("operatore", str(st.session_state.get("username_corrente", "")))
    return m

def carica_prima_nota():
    dati = carica_json(FILE_PRIMA_NOTA, [])
    if not isinstance(dati, list):
        dati = []
    normalizzati = [normalizza_movimento_prima_nota(x) for x in dati if isinstance(x, dict)]
    return normalizzati

def salva_prima_nota(movimenti):
    puliti = [normalizza_movimento_prima_nota(x) for x in (movimenti or []) if isinstance(x, dict)]
    salva_json_sicuro(FILE_PRIMA_NOTA, puliti)
    st.session_state["prima_nota"] = puliti

def movimento_prima_nota_esiste(origine, origine_id):
    """Chiave anti-duplicato pronta per i futuri collegamenti Quote/Magazzino."""
    origine = str(origine or "").strip().upper()
    origine_id = str(origine_id or "").strip()
    if not origine or not origine_id:
        return False
    return any(
        str(m.get("origine", "")).strip().upper() == origine
        and str(m.get("origine_id", "")).strip() == origine_id
        for m in st.session_state.get("prima_nota", [])
    )


def registra_quota_in_prima_nota(atleta, pagamento):
    """Crea una sola ENTRATA di Prima Nota per un pagamento quota già registrato."""
    if not isinstance(atleta, dict) or not isinstance(pagamento, dict):
        return False

    pagamento_id = str(pagamento.get("id", "")).strip()
    if not pagamento_id:
        return False

    # L'ID del pagamento è la chiave stabile anti-duplicato.
    if movimento_prima_nota_esiste("QUOTE", pagamento_id):
        return False

    nome_atleta = f"{atleta.get('cognome', '')} {atleta.get('nome', '')}".strip().title()
    rata = str(pagamento.get("rata", "Pagamento quota") or "Pagamento quota").strip()
    note = str(pagamento.get("note", "") or "").strip()

    movimento = normalizza_movimento_prima_nota({
        "id": uuid.uuid4().hex,
        "data": pagamento.get("data", ora_italiana().strftime("%d/%m/%Y")),
        "timestamp": ora_italiana().isoformat(timespec="seconds"),
        "stagione": atleta.get("stagione", st.session_state.get("stagione_selezionata", "")),
        "tipo": "ENTRATA",
        "categoria": "QUOTE ATLETE",
        "descrizione": f"Quota atleta - {rata}",
        "importo": round(safe_float(pagamento.get("importo", 0)), 2),
        "metodo_pagamento": pagamento.get("metodo", ""),
        "soggetto": nome_atleta,
        "gruppo": atleta.get("gruppo", "") or "",
        "documento": "",
        "note": note,
        "origine": "QUOTE",
        "origine_id": pagamento_id,
        "operatore": pagamento.get("operatore", st.session_state.get("username_corrente", "")),
    })

    if safe_float(movimento.get("importo", 0)) <= 0:
        return False

    movimenti = list(st.session_state.get("prima_nota", []))
    movimenti.append(movimento)
    salva_prima_nota(movimenti)
    return True


def sincronizza_acquisti_magazzino_in_prima_nota():
    """Importa in Prima Nota solo CARICO + causale Acquisto, una sola volta per ID movimento."""
    try:
        movimenti_mag = carica_json(FILE_MAG_MOVIMENTI, [])
        articoli_mag = carica_json(FILE_MAG_ARTICOLI, [])
    except Exception:
        return 0

    if not isinstance(movimenti_mag, list) or not isinstance(articoli_mag, list):
        return 0

    articoli_map = {
        str(a.get("id", "")): a
        for a in articoli_mag
        if isinstance(a, dict) and a.get("id")
    }

    aggiunti = 0
    movimenti_pn = list(st.session_state.get("prima_nota", []))

    # Considera anche quelli aggiunti durante questa stessa sincronizzazione.
    chiavi_esistenti = {
        (
            str(m.get("origine", "")).strip().upper(),
            str(m.get("origine_id", "")).strip()
        )
        for m in movimenti_pn
        if isinstance(m, dict)
    }

    for m in movimenti_mag:
        if not isinstance(m, dict):
            continue
        if str(m.get("tipo", "")).strip().upper() != "CARICO":
            continue
        if str(m.get("causale", "")).strip().lower() != "acquisto":
            continue

        mov_id = str(m.get("id", "")).strip()
        if not mov_id or ("MAGAZZINO", mov_id) in chiavi_esistenti:
            continue

        art = articoli_map.get(str(m.get("articolo_id", "")), {})
        quantita = max(0.0, safe_float(m.get("quantita", 0)))

        # Per i nuovi movimenti il database può salvare il costo storico.
        # Per i movimenti legacy resta compatibile usando il costo articolo.
        costo_unitario = max(
            0.0,
            safe_float(m.get("costo_unitario", art.get("costo", 0)))
        )
        valore = max(
            0.0,
            safe_float(m.get("valore_movimento", quantita * costo_unitario))
        )
        if valore <= 0:
            continue

        data_raw = str(m.get("data", "") or "")
        data_pn = ""
        dt_mov = None
        try:
            dt_mov = datetime.fromisoformat(data_raw.replace("Z", "+00:00"))
            data_pn = dt_mov.strftime("%d/%m/%Y")
        except Exception:
            data_pn = ora_italiana().strftime("%d/%m/%Y")

        if dt_mov:
            anno = dt_mov.year
            stagione_mov = f"{anno}/{anno+1}" if dt_mov.month >= 7 else f"{anno-1}/{anno}"
        else:
            stagione_mov = st.session_state.get("stagione_selezionata", "")

        nome_articolo = str(art.get("nome", "") or "Materiale").strip()
        codice = str(art.get("codice", "") or "").strip()
        descrizione = f"Acquisto magazzino - {nome_articolo}"
        if codice:
            descrizione += f" ({codice})"

        movimento_pn = normalizza_movimento_prima_nota({
            "id": uuid.uuid4().hex,
            "data": data_pn,
            "timestamp": ora_italiana().isoformat(timespec="seconds"),
            "stagione": stagione_mov,
            "tipo": "USCITA",
            "categoria": "MATERIALE SPORTIVO",
            "descrizione": descrizione,
            "importo": round(valore, 2),
            "metodo_pagamento": str(m.get("metodo_pagamento", "") or ""),
            "soggetto": str(m.get("fornitore", art.get("fornitore", "")) or ""),
            "gruppo": "SOCIETÀ",
            "documento": str(m.get("documento", "") or ""),
            "note": str(m.get("note", "") or ""),
            "origine": "MAGAZZINO",
            "origine_id": mov_id,
            "operatore": str(m.get("operatore", "") or st.session_state.get("username_corrente", "")),
        })

        movimenti_pn.append(movimento_pn)
        chiavi_esistenti.add(("MAGAZZINO", mov_id))
        aggiunti += 1

    if aggiunti:
        salva_prima_nota(movimenti_pn)

    return aggiunti


def _data_prima_nota(value):
    txt = str(value or "").strip()
    for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
        try:
            return datetime.strptime(txt, fmt).date()
        except ValueError:
            pass
    return None

def _periodo_stagione(stagione):
    m = re.fullmatch(r"\s*(\d{4})\s*/\s*(\d{4})\s*", str(stagione or ""))
    if m:
        y1, y2 = int(m.group(1)), int(m.group(2))
        try:
            return datetime(y1, 7, 1).date(), datetime(y2, 6, 30).date()
        except ValueError:
            pass
    oggi = ora_italiana().date()
    return oggi.replace(month=1, day=1), oggi.replace(month=12, day=31)

def _df_prima_nota(movimenti):
    righe = []
    for m in movimenti:
        righe.append({
            "Data": m.get("data", ""),
            "Tipo": m.get("tipo", ""),
            "Categoria": m.get("categoria", ""),
            "Descrizione": m.get("descrizione", ""),
            "Importo": safe_float(m.get("importo", 0)),
            "Metodo": m.get("metodo_pagamento", ""),
            "Soggetto": m.get("soggetto", ""),
            "Gruppo": m.get("gruppo", ""),
            "Documento": m.get("documento", ""),
            "Origine": m.get("origine", "MANUALE"),
            "Operatore": m.get("operatore", ""),
            "ID": m.get("id", ""),
        })
    return pd.DataFrame(righe)

def genera_excel_prima_nota(movimenti, stagione):
    df = _df_prima_nota(movimenti)
    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        df.to_excel(writer, index=False, sheet_name="Prima Nota", startrow=4)
        ws = writer.book["Prima Nota"]
        ws["A1"] = f"{nome_societa} - Prima Nota"
        ws["A2"] = f"Stagione: {stagione}"
        entrate = sum(safe_float(x.get("importo", 0)) for x in movimenti if x.get("tipo") == "ENTRATA")
        uscite = sum(safe_float(x.get("importo", 0)) for x in movimenti if x.get("tipo") == "USCITA")
        ws["A3"] = f"Entrate: € {entrate:,.2f} | Uscite: € {uscite:,.2f} | Saldo: € {entrate-uscite:,.2f}"
        ws.freeze_panes = "A6"
        for col in ws.columns:
            max_len = max((len(str(c.value or "")) for c in col), default=0)
            ws.column_dimensions[col[0].column_letter].width = min(max(max_len + 2, 10), 42)
        for row in range(6, ws.max_row + 1):
            ws.cell(row=row, column=5).number_format = '#,##0.00 [$€-it-IT]'
    buffer.seek(0)
    return buffer.getvalue()

def genera_pdf_prima_nota(movimenti, stagione):
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, rightMargin=22, leftMargin=22, topMargin=24, bottomMargin=24)
    styles = getSampleStyleSheet()
    story = [Paragraph(f"<b>{nome_societa} - PRIMA NOTA</b>", styles["Heading1"]),
             Paragraph(f"Stagione {stagione}", styles["Normal"]), Spacer(1, 10)]
    entrate = sum(safe_float(x.get("importo", 0)) for x in movimenti if x.get("tipo") == "ENTRATA")
    uscite = sum(safe_float(x.get("importo", 0)) for x in movimenti if x.get("tipo") == "USCITA")
    story.append(Paragraph(
        f"Entrate: <b>€ {entrate:,.2f}</b> &nbsp;&nbsp; Uscite: <b>€ {uscite:,.2f}</b> &nbsp;&nbsp; Saldo: <b>€ {entrate-uscite:,.2f}</b>",
        styles["Normal"]
    ))
    story.append(Spacer(1, 12))
    dati = [["Data", "Tipo", "Categoria", "Descrizione", "Importo", "Metodo", "Gruppo"]]
    for m in movimenti:
        dati.append([
            str(m.get("data", ""))[:10], str(m.get("tipo", ""))[:8], str(m.get("categoria", ""))[:22],
            str(m.get("descrizione", ""))[:35], f"€ {safe_float(m.get('importo',0)):,.2f}",
            str(m.get("metodo_pagamento", ""))[:13], str(m.get("gruppo", ""))[:13],
        ])
    if len(dati) == 1:
        dati.append(["-", "-", "Nessun movimento", "", "", "", ""])
    tab = Table(dati, repeatRows=1, colWidths=[50, 47, 92, 137, 65, 65, 72])
    tab.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#e9eef5")),
        ("TEXTCOLOR", (0,0), (-1,0), colors.HexColor("#1f2937")),
        ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
        ("FONTNAME", (0,1), (-1,-1), "Helvetica"),
        ("FONTSIZE", (0,0), (-1,-1), 6.5),
        ("GRID", (0,0), (-1,-1), 0.35, colors.HexColor("#cbd5e1")),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
        ("ALIGN", (4,1), (4,-1), "RIGHT"),
        ("ROWBACKGROUNDS", (0,1), (-1,-1), [colors.white, colors.HexColor("#f8fafc")]),
    ]))
    story.append(tab)
    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()

