def crea_scheda_standard(dati, stagione_attiva="2026/2027"):
    gruppo = normalizza_nome_gruppo(dati.get("gruppo", "Minivolley")) or "Minivolley"
    categoria = normalizza_categoria(dati.get("categoria", ""), gruppo)
    config_gruppo = trova_configurazione_quote(gruppo)
    if not config_gruppo or safe_float(config_gruppo.get("quota_tot", 0)) == 0.0:
        quota_default = 500.0
        config_gruppo = {
            "n_rate": "1 Rata", "quota_tot": quota_default,
            "r1_imp": quota_default, "r2_imp": 0.0, "r3_imp": 0.0, "r4_imp": 0.0,
            "r1_data": "", "r2_data": "", "r3_data": "", "r4_data": "",
        }
    standard = {
        "id": uuid.uuid4().hex, "sync_key": "", "cognome": "", "nome": "", "sesso": "M", "cf": "", "data_nas": "", "numero_maglia": "",
        "luogo_nas": "", "prov_nas": "", "indirizzo_res": "", "citta_res": "", "prov_res": "",
        "scuola_frequentata": "", "classe_scolastica": "",
        "categoria": categoria, "gruppo": gruppo, "gruppo2": "", "scad_visita": "",
        "allegato_visita": "", "allegato_privacy": "", "foto_atleta": "", "allegato_altro": "",
        "gen1": "", "tel1": "", "mail1": "", "gen2": "", "tel2": "", "mail2": "",
        "n_rate": config_gruppo.get("n_rate", "1 Rata"), "quota_tot": safe_float(config_gruppo.get("quota_tot", 500.0)),
        "sconto": 0.0, "tot_scontato": 0.0,
        "r1_imp": safe_float(config_gruppo.get("r1_imp", 500.0)), "r1_versato": 0.0, "r1_data": str(config_gruppo.get("r1_data", "")),
        "r2_imp": safe_float(config_gruppo.get("r2_imp", 0.0)), "r2_versato": 0.0, "r2_data": str(config_gruppo.get("r2_data", "")),
        "r3_imp": safe_float(config_gruppo.get("r3_imp", 0.0)), "r3_versato": 0.0, "r3_data": str(config_gruppo.get("r3_data", "")),
        "r4_imp": safe_float(config_gruppo.get("r4_imp", 0.0)), "r4_versato": 0.0, "r4_data": str(config_gruppo.get("r4_data", "")),
        "quota_versata": 0.0, "saldo_rimanente": 0.0, "rate_pagate_str": "0/1", "stato_rate": "🔴 INCOMPLETA",
        "stato": "Confermato", "stagione": stagione_attiva, "matricola_fipav": "", "storico_pagamenti": [], "valutazioni_tecniche": {},
    }
    for k, v in dati.items():
        if k in standard and v != "":
            standard[k] = str(v).strip() if isinstance(v, str) else v
    standard["categoria"] = normalizza_categoria(standard.get("categoria"), standard.get("gruppo", ""))
    return ricalcola_finanze(standard)
