        destinazione = folder / "Informativa_privacy_societa.pdf"
        destinazione.write_bytes(upload_modello.getvalue())
        drive_modello = carica_documento_su_google_drive(destinazione.read_bytes(), destinazione.name, atleta=None, tipo="MODELLI_PRIVACY", stagione="GENERALE")
        config_societa["privacy_modello_path"] = str(destinazione)
