def _organigramma_id(*parti):
    testo = "|".join(str(x or "").strip().casefold() for x in parti)
    return hashlib.sha1(testo.encode("utf-8")).hexdigest()[:16]


def _organigramma_livello(ruolo):
    ruolo_key = _gruppo_key_compact(ruolo)
    if any(x in ruolo_key for x in ("direttoregenerale", "presidente")):
        return 1
    if any(x in ruolo_key for x in ("direttoretecnico", "responsabilesettore", "responsabilegenerale")):
        return 2
    if any(x in ruolo_key for x in ("coordinatore", "responsabile", "direttoresportivo")):
        return 3
    if any(x in ruolo_key for x in ("2allenatore", "3allenatore", "assistente", "aiutoallenatore")):
        return 5
    return 4


