                        firma_path = Path(str(contratto_firmato.get("firma_collaboratore_path", "")))
                        sigla_path = Path(str(contratto_firmato.get("sigla_collaboratore_path", "")))
                        firma_societa_path = Path(str(contratto_firmato.get("firma_societa_path", "")))
                        firme_recuperabili = firma_path.is_file() and sigla_path.is_file()
