                    scelta_annulla = st.selectbox("Contratto da annullare", list(mappa_pendenti), key=f"contratto_staff_annulla_scelta_{persona.get('id','')}")
                    conferma_annulla = st.checkbox("Confermo l’annullamento: il collegamento di firma verrà disattivato", key=f"contratto_staff_annulla_conferma_{persona.get('id','')}")
                    if st.button("ANNULLA CONTRATTO SELEZIONATO", type="secondary", use_container_width=True, disabled=not conferma_annulla, key=f"contratto_staff_annulla_btn_{persona.get('id','')}"):
                        contratto_annullato = mappa_pendenti[scelta_annulla]
