        incarichi_persona = persona.get("incarichi_squadre", []) or []
        righe_iniziali = []
        for incarico_persona in incarichi_persona:
            if not isinstance(incarico_persona, dict): continue
            squadre_incarico = incarico_persona.get("squadre", []) or [""]
            for squadra_incarico in squadre_incarico:
                righe_iniziali.append({"Ruolo / attività": _staff_ruolo_visualizzato(persona, incarico_persona.get("ruolo", "")), "Squadra / area": squadra_incarico, "Importo mensile (€)": 0.0, "Mensilità": 9, "Inizio rimborso": "Automatico", "Rimborso aggiuntivo (€)": 0.0})
        if not righe_iniziali:
            righe_iniziali = [{"Ruolo / attività": next(iter(_staff_ruoli_visualizzati(persona)), "Collaboratore sportivo"), "Squadra / area": "", "Importo mensile (€)": 0.0, "Mensilità": 9, "Inizio rimborso": "Automatico", "Rimborso aggiuntivo (€)": 0.0}]
        dati_incarichi_key = f"contratto_incarichi_dati_{persona.get('id','')}"
        editor_incarichi_key = f"contratto_incarichi_{persona.get('id','')}"
        if dati_incarichi_key not in st.session_state:
            st.session_state[dati_incarichi_key] = righe_iniziali
        righe_editor = []
        for riga_salvata in st.session_state[dati_incarichi_key]:
            riga_calcolata = dict(riga_salvata)
            riga_calcolata["Totale incarico (€)"] = round(
                max(0.0, safe_float(riga_salvata.get("Importo mensile (€)", 0)))
                * int(max(0, safe_float(riga_salvata.get("Mensilità", 0))))
                + max(0.0, safe_float(riga_salvata.get("Rimborso aggiuntivo (€)", 0))), 2
            )
            righe_editor.append(riga_calcolata)
        incarichi_df = st.data_editor(
            pd.DataFrame(righe_editor), num_rows="dynamic", hide_index=True, use_container_width=True,
            key=editor_incarichi_key, disabled=["Totale incarico (€)"],
            column_config={
                "Ruolo / attività": st.column_config.SelectboxColumn("Ruolo / attività", options=list(dict.fromkeys(STAFF_RUOLI_SQUADRA[1:] + _staff_ruoli_visualizzati(persona) + ["Collaboratore sportivo"])), required=True),
                "Squadra / area": st.column_config.SelectboxColumn("Squadra / area", options=_staff_squadre_disponibili(stagione_selezionata), required=True),
                "Importo mensile (€)": st.column_config.NumberColumn("Importo mensile (€)", min_value=0.0, step=10.0, format="€ %.2f"),
                "Mensilità": st.column_config.NumberColumn("Mensilità", min_value=0, max_value=24, step=1, format="%d"),
                "Inizio rimborso": st.column_config.SelectboxColumn("Inizio rimborso", options=["Automatico"] + MESI_ITALIANI, required=True),
                "Rimborso aggiuntivo (€)": st.column_config.NumberColumn("Rimborso aggiuntivo (€)", min_value=0.0, step=10.0, format="€ %.2f"),
                "Totale incarico (€)": st.column_config.NumberColumn("Totale incarico (€)", min_value=0.0, format="€ %.2f", disabled=True),
            },
        )
        colonne_editabili = ["Ruolo / attività", "Squadra / area", "Importo mensile (€)", "Mensilità", "Inizio rimborso", "Rimborso aggiuntivo (€)"]
        righe_modificate = []
        for _, riga_modificata in incarichi_df.iterrows():
            righe_modificate.append({
                "Ruolo / attività": "" if pd.isna(riga_modificata.get("Ruolo / attività")) else str(riga_modificata.get("Ruolo / attività", "")),
                "Squadra / area": "" if pd.isna(riga_modificata.get("Squadra / area")) else str(riga_modificata.get("Squadra / area", "")),
                "Importo mensile (€)": max(0.0, safe_float(riga_modificata.get("Importo mensile (€)", 0))),
                "Mensilità": int(max(0, safe_float(riga_modificata.get("Mensilità", 0)))),
                "Inizio rimborso": str(riga_modificata.get("Inizio rimborso", "Automatico") or "Automatico"),
                "Rimborso aggiuntivo (€)": max(0.0, safe_float(riga_modificata.get("Rimborso aggiuntivo (€)", 0))),
            })
        confronto_corrente = json.dumps(st.session_state[dati_incarichi_key], ensure_ascii=False, sort_keys=True, default=str)
        confronto_modificato = json.dumps(righe_modificate, ensure_ascii=False, sort_keys=True, default=str)
        if confronto_corrente != confronto_modificato:
            st.session_state[dati_incarichi_key] = righe_modificate
            st.session_state.pop(editor_incarichi_key, None)
            st.rerun()
        incarichi_economici = []
        for _, riga_incarico in incarichi_df.fillna(0).iterrows():
            ruolo_riga = str(riga_incarico.get("Ruolo / attività", "")).strip()
            gruppo_riga = str(riga_incarico.get("Squadra / area", "")).strip()
            if ruolo_riga or gruppo_riga:
                incarichi_economici.append({"ruolo": ruolo_riga or "Collaboratore sportivo", "gruppo": gruppo_riga, "rimborso_mensile": max(0.0,safe_float(riga_incarico.get("Importo mensile (€)",0))), "numero_mesi": int(max(0,safe_float(riga_incarico.get("Mensilità",0)))), "mese_inizio_rimborso": _staff_mese_inizio_rimborso_numero(riga_incarico.get("Inizio rimborso")), "rimborso_forfettario": max(0.0,safe_float(riga_incarico.get("Rimborso aggiuntivo (€)",0)))})
        totale_anteprima = round(sum(x["rimborso_mensile"]*x["numero_mesi"]+x["rimborso_forfettario"] for x in incarichi_economici),2)
        st.info(f"Totale previsto dal contratto: € {totale_anteprima:,.2f}")
        d1, d2, d3 = st.columns(3)
        data_inizio = d1.date_input("Data inizio", value=date(ora_italiana().year, 9, 1), key=f"contratto_inizio_{persona.get('id','')}")
