def _presenze_testo_normale(value):
    return "".join(
        ch for ch in unicodedata.normalize("NFKD", str(value or "")).casefold()
        if ch.isalnum()
    )


def _presenze_data_normale(value):
    return "".join(ch for ch in str(value or "") if ch.isdigit())


def _presenze_data_calendario_valida(value):
    try:
        datetime.strptime(str(value or "").strip(), "%d/%m/%Y")
        return True
    except (TypeError, ValueError):
        return False


def _presenze_configurazioni_qr():
    cfg = config_societa.setdefault("presenze_qr_stagionali", {})
    if not isinstance(cfg, dict):
        cfg = {}
        config_societa["presenze_qr_stagionali"] = cfg
    return cfg


def _presenze_config_da_token(token):
    token = str(token or "").strip()
    configurazioni = (carica_json(FILE_CONFIG_SOCIETA, {}) or {}).get("presenze_qr_stagionali", {})
    if not isinstance(configurazioni, dict):
        return None
    for voce in configurazioni.values():
        if isinstance(voce, dict) and hmac.compare_digest(str(voce.get("token", "")), token):
            return voce
    return None


def _presenze_salva_registrazione(voce):
    presenze = carica_json(FILE_PRESENZE_PROMO, [])
    if not isinstance(presenze, list):
        presenze = []
    chiave = str(voce.get("chiave_unica", ""))
    esistente = next((x for x in presenze if str(x.get("chiave_unica", "")) == chiave), None)
    if esistente:
        return False, "La presenza di oggi risulta gia registrata. Per correggerla rivolgiti alla segreteria o all'istruttore."
    presenze.append(voce)
    salva_json_sicuro(FILE_PRESENZE_PROMO, presenze)
    return True, "Presenza registrata correttamente. Grazie!"


def _presenze_import_excel_template():
    esempio = pd.DataFrame([
        {"Data": ora_italiana().strftime("%d/%m/%Y"), "Gruppo": "UNDER 14", "Cognome": "ROSSI", "Nome": "ANNA", "Tipo": "PRESENTE", "Note": ""},
        {"Data": ora_italiana().strftime("%d/%m/%Y"), "Gruppo": "MINIVOLLEY", "Cognome": "BIANCHI", "Nome": "LUCA", "Tipo": "PROVA", "Note": "Prima prova"},
    ])
    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        esempio.to_excel(writer, index=False, sheet_name="Presenze")
    return buffer.getvalue()


def _presenze_import_data(value):
    try:
        if value is None or pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(value, pd.Timestamp): return value.date()
    if isinstance(value, datetime): return value.date()
    if isinstance(value, date): return value
    testo = str(value).strip()
    for formato in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%d/%m/%y"):
        try: return datetime.strptime(testo, formato).date()
        except ValueError: pass
    parsed = pd.to_datetime(testo, errors="coerce", dayfirst=True)
    return parsed.date() if pd.notna(parsed) else None


def _presenze_import_testo(value):
    try:
        if value is None or pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    if isinstance(value, (pd.Timestamp, datetime, date)):
        return value.strftime("%d/%m/%Y")
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def _presenze_leggi_file_tabellare(file_bytes, nome_file=""):
    """Legge il primo foglio da Excel oppure OpenDocument senza dipendenze ODS aggiuntive."""
    estensione = Path(str(nome_file or "")).suffix.casefold()
    if estensione != ".ods":
        return pd.read_excel(io.BytesIO(file_bytes), sheet_name=0, dtype=object)
    try:
        return pd.read_excel(io.BytesIO(file_bytes), sheet_name=0, dtype=object, engine="odf")
    except (ImportError, ModuleNotFoundError):
        pass
    namespace = {
        "office": "urn:oasis:names:tc:opendocument:xmlns:office:1.0",
        "table": "urn:oasis:names:tc:opendocument:xmlns:table:1.0",
        "text": "urn:oasis:names:tc:opendocument:xmlns:text:1.0",
    }
    with zipfile.ZipFile(io.BytesIO(file_bytes)) as archivio_ods:
        radice = ET.fromstring(archivio_ods.read("content.xml"))
    foglio = radice.find(".//table:table", namespace)
    if foglio is None:
        return pd.DataFrame()
    righe = []
    attr_righe = f"{{{namespace['table']}}}number-rows-repeated"
    attr_colonne = f"{{{namespace['table']}}}number-columns-repeated"
    attributi_valore = [
        f"{{{namespace['office']}}}string-value", f"{{{namespace['office']}}}date-value",
        f"{{{namespace['office']}}}time-value", f"{{{namespace['office']}}}value",
        f"{{{namespace['office']}}}boolean-value",
    ]
    for nodo_riga in foglio.findall("table:table-row", namespace):
        valori = []
        for cella in list(nodo_riga):
            if not cella.tag.endswith(("table-cell", "covered-table-cell")):
                continue
            paragrafi = ["".join(p.itertext()).strip() for p in cella.findall(".//text:p", namespace)]
            valore = "\n".join(x for x in paragrafi if x)
            if not valore:
                valore = next((cella.get(attributo) for attributo in attributi_valore if cella.get(attributo) is not None), "")
            ripetizioni = min(max(1, int(cella.get(attr_colonne, "1") or 1)), 500)
            valori.extend([valore] * ripetizioni)
        while valori and valori[-1] in {"", None}:
            valori.pop()
        ripetizioni_riga = min(max(1, int(nodo_riga.get(attr_righe, "1") or 1)), 500)
        if valori:
            righe.extend([list(valori) for _ in range(ripetizioni_riga)])
    if not righe:
        return pd.DataFrame()
    intestazioni = [str(x or "").strip() or f"Colonna {i + 1}" for i, x in enumerate(righe[0])]
    uniche, conteggi = [], {}
    for intestazione in intestazioni:
        conteggi[intestazione] = conteggi.get(intestazione, 0) + 1
        uniche.append(intestazione if conteggi[intestazione] == 1 else f"{intestazione}_{conteggi[intestazione]}")
    larghezza = len(uniche)
    dati = [(riga + [None] * larghezza)[:larghezza] for riga in righe[1:]]
    return pd.DataFrame(dati, columns=uniche)


def _presenze_importa_excel(file_bytes, stagione, allen_db, nome_file="", gruppo_predefinito=""):
    raw = _presenze_leggi_file_tabellare(file_bytes, nome_file)
    if raw.empty:
        return {"importate": 0, "aggiornate": 0, "create_sedute": 0, "errori": ["Il file non contiene righe."]}
    alias = {
        "data": "data", "giorno": "data", "data allenamento": "data",
        "gruppo": "gruppo", "squadra": "gruppo", "categoria": "gruppo",
        "cognome": "cognome", "nome": "nome", "tipo": "tipo", "stato": "tipo",
        "presenza": "tipo", "note": "note", "nota": "note", "ora": "ora",
        "fonte": "fonte", "stato prova": "stato_prova",
        "genitore accompagnatore": "genitore", "genitore": "genitore",
        "telefono genitore": "telefono_genitore", "email genitore": "email_genitore",
        "visita medica": "visita_medica", "prenotata il": "prenotata_il",
    }
    colonne = {}
    for colonna in raw.columns:
        normalizzata = normalizza_intestazione_colonna(colonna)
        if normalizzata in alias and alias[normalizzata] not in colonne:
            colonne[alias[normalizzata]] = colonna
    nome_normale = _presenze_testo_normale(Path(str(nome_file or "")).stem)
    gruppo_inferito = str(gruppo_predefinito or "").strip()
    if not gruppo_inferito or gruppo_inferito.upper() == "AUTO":
        if "minivolley" in nome_normale:
            gruppo_inferito = "MINIVOLLEY"
        elif "scuola" in nome_normale:
            gruppo_inferito = "SCUOLA"
        else:
            gruppo_inferito = ""
    richieste = ["data", "cognome", "nome", "tipo"]
    if "gruppo" not in colonne and not gruppo_inferito:
        richieste.append("gruppo")
    mancanti = [x for x in richieste if x not in colonne]
    if mancanti:
        return {"importate": 0, "aggiornate": 0, "create_sedute": 0, "errori": ["Colonne mancanti: " + ", ".join(mancanti)]}
    atlete = [a for a in st.session_state.get("elenco_atlete", []) if str(a.get("stagione", "")) == str(stagione) and a.get("cognome") != "--- Inizializzazione"]
    squadre = st.session_state.get("squadre_campionati", {}).get(stagione, []) or []
    sedute = allen_db.setdefault(stagione, [])
    promo = _presenze_rileggi_da_drive(FILE_PRESENZE_PROMO, [])
    if not isinstance(promo, list): promo = []
    importate = aggiornate = create_sedute = ignorate = 0
    errori = []
    for indice, riga in raw.iterrows():
        numero_riga = indice + 2
        giorno = _presenze_import_data(riga.get(colonne["data"]))
        gruppo = _presenze_import_testo(riga.get(colonne["gruppo"], "")) if "gruppo" in colonne else gruppo_inferito
        cognome = _presenze_import_testo(riga.get(colonne["cognome"], ""))
        nome = _presenze_import_testo(riga.get(colonne["nome"], ""))
        tipo = (_presenze_import_testo(riga.get(colonne["tipo"], "PRESENTE")) or "PRESENTE").upper()
        note = _presenze_import_testo(riga.get(colonne.get("note"), "")) if colonne.get("note") else ""
        ora = _presenze_import_testo(riga.get(colonne.get("ora"), "")) if colonne.get("ora") else ""
        fonte = _presenze_import_testo(riga.get(colonne.get("fonte"), "")) if colonne.get("fonte") else ""
        stato_prova = _presenze_import_testo(riga.get(colonne.get("stato_prova"), "")) if colonne.get("stato_prova") else ""
        genitore = _presenze_import_testo(riga.get(colonne.get("genitore"), "")) if colonne.get("genitore") else ""
        telefono_genitore = _presenze_import_testo(riga.get(colonne.get("telefono_genitore"), "")) if colonne.get("telefono_genitore") else ""
        email_genitore = _presenze_import_testo(riga.get(colonne.get("email_genitore"), "")) if colonne.get("email_genitore") else ""
        visita_medica = _presenze_import_testo(riga.get(colonne.get("visita_medica"), "")) if colonne.get("visita_medica") else ""
        prenotata_il = _presenze_import_testo(riga.get(colonne.get("prenotata_il"), "")) if colonne.get("prenotata_il") else ""
        if not giorno:
            ignorate += 1
            continue
        if not giorno or not gruppo or not cognome or not nome:
            errori.append(f"Riga {numero_riga}: data, gruppo, cognome o nome mancanti."); continue
        if tipo not in {"PRESENTE", "PROVA", "RECUPERO", "ASSENTE", "GIUSTIFICATA", "INFORTUNATA"}:
            errori.append(f"Riga {numero_riga}: tipo '{tipo}' non riconosciuto."); continue
        gruppo_norm = _presenze_testo_normale(gruppo)
        data_testo, data_iso = giorno.strftime("%d/%m/%Y"), giorno.strftime("%Y-%m-%d")
        candidati = [a for a in atlete if _presenze_testo_normale(a.get("cognome", "")) == _presenze_testo_normale(cognome) and _presenze_testo_normale(a.get("nome", "")) == _presenze_testo_normale(nome)]
        atleta = next((a for a in candidati if gruppo_norm in {_presenze_testo_normale(a.get("gruppo", "")), _presenze_testo_normale(a.get("gruppo2", ""))}), None) or (candidati[0] if len(candidati) == 1 else None)
        if gruppo_norm in {"minivolley", "scuola"} or tipo == "PROVA":
            identita = str(atleta.get("id", "")) if atleta else _presenze_testo_normale(f"{cognome}|{nome}")
            chiave = f"{stagione}|{gruppo_norm}|{data_iso}|{'PROVA|' if tipo == 'PROVA' else ''}{identita}"
            esistente = next((x for x in promo if str(x.get("chiave_unica", "")) == chiave), None)
            dati = {"data": data_testo, "data_iso": data_iso, "ora": ora or ora_italiana().strftime("%H:%M:%S"), "stagione": stagione, "gruppo": gruppo, "atleta_id": str(atleta.get("id", "")) if atleta else "", "cognome": cognome.upper(), "nome": nome.upper(), "tipo": tipo, "fonte": fonte or "IMPORTAZIONE EXCEL", "stato_prova": stato_prova or ("EFFETTUATA" if tipo == "PROVA" else ""), "genitore": genitore, "telefono_genitore": telefono_genitore, "email_genitore": email_genitore, "visita_medica": visita_medica, "prenotata_il": prenotata_il, "note": note, "registrato_da": st.session_state.get("username_corrente", "")}
            if esistente: esistente.update(dati); aggiornate += 1
            else: promo.append({"id": uuid.uuid4().hex, "chiave_unica": chiave, **dati}); importate += 1
            continue
        if not atleta:
            errori.append(f"Riga {numero_riga}: atleta {cognome} {nome} non trovata nell’anagrafica."); continue
        squadra = next((s for s in squadre if gruppo_norm in {_presenze_testo_normale(s.get("nome", "")), _presenze_testo_normale(s.get("gruppo", ""))}), None)
        nomi_seduta = {gruppo_norm, _presenze_testo_normale((squadra or {}).get("nome", ""))}
        seduta = next((s for s in sedute if str(s.get("data", "")) == data_testo and _presenze_testo_normale(s.get("squadra", "")) in nomi_seduta), None)
        if seduta is None:
            seduta = {"id": uuid.uuid4().hex, "data": data_testo, "squadra_id": (squadra or {}).get("id", ""), "squadra": (squadra or {}).get("nome", gruppo), "tipo": "Allenamento", "ora_inizio": ora, "ora_fine": "", "palestra": "", "note": "Seduta creata da importazione Excel", "convocati_ids": [str(x) for x in ((squadra or {}).get("roster_ids", []) or [])], "presenze": {}, "importato_da_excel": True, "creato_il": ora_italiana().isoformat(timespec="seconds"), "operatore": st.session_state.get("username_corrente", "")}
            sedute.append(seduta); create_sedute += 1
        atleta_id = str(atleta.get("id", "")); precedente = seduta.setdefault("presenze", {}).get(atleta_id)
        stato = {"PRESENTE": "Presente", "RECUPERO": "Presente", "ASSENTE": "Assente", "GIUSTIFICATA": "Giustificata", "INFORTUNATA": "Infortunata"}.get(tipo, "Presente")
        seduta["presenze"][atleta_id] = {"stato": stato, "note": note, "tipo": tipo, "fonte": "IMPORTAZIONE EXCEL", "operatore": st.session_state.get("username_corrente", "")}
        if precedente: aggiornate += 1
        else: importate += 1
    salva_json_sicuro(FILE_PRESENZE_PROMO, promo)
    salva_json_sicuro(FILE_ALLENAMENTI, allen_db)
    st.session_state["presenze_promozionale"] = promo
    st.session_state["allenamenti_tecnici"] = allen_db
    return {"importate": importate, "aggiornate": aggiornate, "create_sedute": create_sedute, "ignorate": ignorate, "gruppo_usato": gruppo_inferito, "errori": errori}


def _presenze_collega_promo_agli_allenamenti(allenamenti_db, stagione, registrazioni=None):
    """Collega le registrazioni QR Mini/Scuola alla seduta stagionale dello stesso giorno.

    Le persone iscritte vengono registrate nella normale mappa presenze della seduta.
    Le prove, che non possiedono ancora un id atleta, restano in un elenco separato
    della stessa seduta e partecipano comunque ai riepiloghi e alle statistiche.
    L'operazione e' idempotente e non sovrascrive correzioni manuali successive.
    """
    if not isinstance(allenamenti_db, dict):
        return {"collegate": 0, "iscritte": 0, "prove": 0, "senza_seduta": 0, "modificato": False}
    sedute = allenamenti_db.get(str(stagione), [])
    if not isinstance(sedute, list):
        return {"collegate": 0, "iscritte": 0, "prove": 0, "senza_seduta": 0, "modificato": False}
    if registrazioni is None:
        registrazioni = _presenze_rileggi_da_drive(FILE_PRESENZE_PROMO, [])
    if not isinstance(registrazioni, list):
        registrazioni = []

    def _minuti_orario(valore):
        m = re.search(r"(\d{1,2}):(\d{2})", str(valore or ""))
        return int(m.group(1)) * 60 + int(m.group(2)) if m else 0

    collegate = iscritte = prove = senza_seduta = 0
    modificato = False
    for registrazione in registrazioni:
        if str(registrazione.get("stagione", "")) != str(stagione):
            continue
        gruppo_norm = _presenze_testo_normale(registrazione.get("gruppo", ""))
        if gruppo_norm not in {"minivolley", "scuola"}:
            continue
        data_reg = str(registrazione.get("data", "")).strip()
        if not data_reg and re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(registrazione.get("data_iso", ""))):
            try:
                data_reg = datetime.strptime(str(registrazione.get("data_iso")), "%Y-%m-%d").strftime("%d/%m/%Y")
            except ValueError:
                data_reg = ""
        candidate = [
            seduta for seduta in sedute
            if str(seduta.get("data", "")).strip() == data_reg
            and _presenze_testo_normale(seduta.get("squadra", "")) == gruppo_norm
            and not bool(seduta.get("non_svolto", False))
        ]
        if not candidate:
            senza_seduta += 1
            continue
        minuto_reg = _minuti_orario(registrazione.get("ora", ""))
        seduta = min(candidate, key=lambda x: abs(_minuti_orario(x.get("ora_inizio", "")) - minuto_reg))
        tipo = str(registrazione.get("tipo", "PRESENTE")).strip().upper()
        stato = {
            "PRESENTE": "Presente", "RECUPERO": "Presente", "PROVA": "Presente",
            "ASSENTE": "Assente", "GIUSTIFICATA": "Giustificata", "INFORTUNATA": "Infortunata",
        }.get(tipo, "Presente")
        atleta_id = str(registrazione.get("atleta_id", "")).strip()
        registro_id = str(registrazione.get("id") or registrazione.get("chiave_unica") or uuid.uuid4().hex)
        if atleta_id:
            esterni_esistenti = seduta.get("partecipanti_qr_esterni", {}) or {}
            if isinstance(esterni_esistenti, dict) and registro_id in esterni_esistenti:
                esterni_esistenti.pop(registro_id, None)
                seduta["partecipanti_qr_esterni"] = esterni_esistenti
                modificato = True
            convocati = [str(x) for x in (seduta.get("convocati_ids", []) or [])]
            if atleta_id not in convocati:
                convocati.append(atleta_id)
                seduta["convocati_ids"] = convocati
                modificato = True
            presenze_seduta = seduta.setdefault("presenze", {})
            precedente = presenze_seduta.get(atleta_id, {})
            precedente_stato = precedente.get("stato", "Da registrare") if isinstance(precedente, dict) else str(precedente or "Da registrare")
            precedente_fonte = precedente.get("fonte", "") if isinstance(precedente, dict) else ""
            if precedente_stato == "Da registrare" or precedente_fonte == "QR MINI/SCUOLA":
                nuova_voce = dict(precedente) if isinstance(precedente, dict) else {}
                nuova_voce.update({
                    "stato": stato, "note": str(registrazione.get("note", "") or ""),
                    "fonte": "QR MINI/SCUOLA", "registrazione_promo_id": registro_id,
                    "ora_registrazione": registrazione.get("ora", ""),
                })
                if nuova_voce != precedente:
                    presenze_seduta[atleta_id] = nuova_voce
                    modificato = True
            iscritte += 1
        else:
            esterni = seduta.setdefault("partecipanti_qr_esterni", {})
            nuova_prova = {
                "id": registro_id, "cognome": registrazione.get("cognome", ""),
                "nome": registrazione.get("nome", ""), "data_nascita": registrazione.get("data_nascita", ""),
                "tipo": tipo, "stato": stato, "ora": registrazione.get("ora", ""),
                "fonte": registrazione.get("fonte", "QR STAGIONALE"),
                "telefono": registrazione.get("telefono", ""),
                "visita_medica": registrazione.get("visita_medica_prova", ""),
                "data_prenotazione_visita": registrazione.get("data_prenotazione_visita", ""),
                "note": registrazione.get("note", ""),
            }
            if esterni.get(registro_id) != nuova_prova:
                esterni[registro_id] = nuova_prova
                modificato = True
            prove += 1
        collegate += 1
    return {
        "collegate": collegate, "iscritte": iscritte, "prove": prove,
        "senza_seduta": senza_seduta, "modificato": modificato,
    }


def mostra_qr_presenze(link, titolo, key, etichetta=None):
    link = str(link or "").strip()
    if not link.startswith(("http://", "https://")):
        return
    gruppo_etichetta = str(titolo or '').split('_', 1)[0].replace('-', ' ').strip()
    svg = _qr_svg_con_etichetta(link, str(etichetta or f"PROVA {gruppo_etichetta}"))
    q1, q2 = st.columns([1, 2.4], vertical_alignment="center")
    with q1:
        if svg:
            svg_b64 = base64.b64encode(svg.encode("utf-8")).decode("ascii")
            st.markdown(
                f'<img src="data:image/svg+xml;base64,{svg_b64}" width="220" height="245" alt="Codice QR presenze">',
                unsafe_allow_html=True,
            )
    with q2:
        st.write("Stampa ed esponi questo QR in palestra: rimane valido per tutta la stagione finche non viene disattivato.")
        st.code(link, language=None)
        st.link_button("APRI PAGINA PRESENZE", link, use_container_width=True)
        if svg:
            st.download_button(
                "SCARICA QR DA STAMPARE", svg.encode("utf-8"),
                file_name=f"QR_PRESENZE_{_firma_modulo_nome_sicuro(titolo)}.svg",
                mime="image/svg+xml", use_container_width=True,
                key=f"qr_presenze_download_{key}", on_click="ignore",
            )


def render_presenze_qr_pubbliche(token):
    configurazione = _presenze_config_da_token(token)
    if not configurazione or not configurazione.get("attivo", True):
        st.error("Questo codice QR non e' attivo.")
        return
    stagione = str(configurazione.get("stagione", ""))
    gruppo = str(configurazione.get("gruppo", ""))
    oggi = ora_italiana()
    st.markdown(f"<h2 style='text-align:center;color:#0b5fa5;'>🏐 PRESENZA {gruppo}</h2>", unsafe_allow_html=True)
    st.markdown(f"<p style='text-align:center;'>Stagione {stagione} · {oggi.strftime('%d/%m/%Y')}</p>", unsafe_allow_html=True)
    st.info("La registrazione vale per la giornata odierna. L'elenco completo dei bambini non viene mostrato.")

    tab_iscritto, tab_prova = st.tabs(["✅ Bambino/a iscritto/a", "🌟 Prima prova"])
    with tab_iscritto:
        with st.form(f"presenze_qr_iscritto_{str(token)[:10]}"):
            cognome = st.text_input("Cognome del bambino/a")
            data_nascita = st.text_input("Data di nascita", placeholder="GG/MM/AAAA")
            registrato_da = st.text_input("Nome e cognome del genitore/accompagnatore")
            tipo = st.selectbox("Tipo di presenza", ["PRESENTE", "RECUPERO"])
            conferma = st.checkbox("Confermo che i dati inseriti sono corretti")
            invia = st.form_submit_button("REGISTRA PRESENZA", type="primary", use_container_width=True)
        if invia:
            atlete = [
                a for a in carica_atlete()
                if str(a.get("stagione", "")) == stagione
                and _presenze_testo_normale(a.get("gruppo", "")) == _presenze_testo_normale(gruppo)
                and a.get("cognome") != "--- Inizializzazione"
            ]
            corrispondenze = [
                a for a in atlete
                if _presenze_testo_normale(a.get("cognome", "")) == _presenze_testo_normale(cognome)
                and _presenze_data_normale(a.get("data_nas", "")) == _presenze_data_normale(data_nascita)
            ]
            if not conferma:
                st.error("Conferma i dati prima di registrare la presenza.")
            elif len(str(registrato_da).strip()) < 5:
                st.error("Inserisci nome e cognome del genitore/accompagnatore.")
            elif len(corrispondenze) != 1:
                st.error("Dati non riconosciuti. Controlla cognome, data di nascita e gruppo oppure rivolgiti all'istruttore.")
            else:
                atleta = corrispondenze[0]
                giorno = oggi.strftime("%Y-%m-%d")
                voce = {
                    "id": uuid.uuid4().hex,
                    "chiave_unica": f"{stagione}|{_presenze_testo_normale(gruppo)}|{giorno}|{atleta.get('id','')}",
                    "data": oggi.strftime("%d/%m/%Y"), "data_iso": giorno,
                    "ora": oggi.strftime("%H:%M:%S"), "stagione": stagione, "gruppo": gruppo,
                    "atleta_id": str(atleta.get("id", "")),
                    "cognome": str(atleta.get("cognome", "")), "nome": str(atleta.get("nome", "")),
                    "tipo": tipo, "fonte": "QR STAGIONALE", "registrato_da": registrato_da.strip(),
                    "operatore": "AUTOREGISTRAZIONE", "note": "",
                }
                ok, messaggio = _presenze_salva_registrazione(voce)
                (st.success if ok else st.warning)(messaggio)

    with tab_prova:
        with st.form(f"presenze_qr_prova_{str(token)[:10]}"):
            p1, p2 = st.columns(2)
            nome_prova = p1.text_input("Nome del bambino/a")
            cognome_prova = p2.text_input("Cognome del bambino/a")
            data_prova = st.text_input("Data di nascita del bambino/a", placeholder="GG/MM/AAAA")
            genitore_prova = st.text_input("Nome e cognome del genitore/accompagnatore")
            telefono_prova = st.text_input("Telefono del genitore/accompagnatore")
            email_prova = st.text_input("Email del genitore/accompagnatore (facoltativa)")
            visita_medica_prova = st.selectbox(
                "Visita medica", ["SÌ", "NO"],
                help="Se scegli NO, indica sotto la data in cui la visita è stata prenotata."
            )
            data_visita_prova = st.text_input(
                "Prenotata il (obbligatorio se hai scelto NO)",
                placeholder="GG/MM/AAAA",
                help="Indica la data della prenotazione della visita medica."
            )
            privacy_prova = st.checkbox("Autorizzo la registrazione di questi dati per gestire la prova e la presenza")
            invia_prova = st.form_submit_button("REGISTRA PRIMA PROVA", type="primary", use_container_width=True)
        if invia_prova:
            if not nome_prova.strip() or not cognome_prova.strip() or not _presenze_data_normale(data_prova):
                st.error("Completa nome, cognome e data di nascita del bambino/a.")
            elif len(genitore_prova.strip()) < 5 or not privacy_prova:
                st.error("Inserisci il genitore/accompagnatore e conferma l'autorizzazione.")
            elif visita_medica_prova == "NO" and not _presenze_data_calendario_valida(data_visita_prova):
                st.error("Inserisci la data di prenotazione della visita medica nel formato GG/MM/AAAA.")
            else:
                giorno = oggi.strftime("%Y-%m-%d")
                identita = _presenze_testo_normale(f"{cognome_prova}|{nome_prova}|{data_prova}")
                voce = {
                    "id": uuid.uuid4().hex, "chiave_unica": f"{stagione}|{_presenze_testo_normale(gruppo)}|{giorno}|PROVA|{identita}",
                    "data": oggi.strftime("%d/%m/%Y"), "data_iso": giorno,
                    "ora": oggi.strftime("%H:%M:%S"), "stagione": stagione, "gruppo": gruppo,
                    "atleta_id": "", "cognome": cognome_prova.strip().upper(), "nome": nome_prova.strip().upper(),
                    "data_nascita": data_prova.strip(), "tipo": "PROVA", "fonte": "QR STAGIONALE",
                    "registrato_da": genitore_prova.strip(), "telefono": telefono_prova.strip(),
                    "email_genitore": email_prova.strip(),
                    "visita_medica_prova": visita_medica_prova,
                    "data_prenotazione_visita": data_visita_prova.strip() if visita_medica_prova == "NO" else "",
                    "operatore": "AUTOREGISTRAZIONE", "note": "DA VERIFICARE / EVENTUALE ISCRIZIONE",
                }
                ok, messaggio = _presenze_salva_registrazione(voce)
                (st.success if ok else st.warning)(messaggio)


def _link_modulo_iscrizione_nativo():
    # Nel gestionale Monviso resta attivo il modulo ufficiale storico esterno.
    # Il modulo nativo configurabile e' riservato al gestionale Master.
    if str(LINK_GOOGLE_FORM).strip().startswith(("http://", "https://")):
        return str(LINK_GOOGLE_FORM).strip()
    cfg = config_societa.get("modulo_iscrizione_nativo", {})
    if not isinstance(cfg, dict) or not cfg.get("attivo") or not cfg.get("token"):
        return ""
    base_url = str(_segreto("APP_PUBLIC_URL", "") or cfg.get("base_url", "")).strip().rstrip("/")
    return f"{base_url}?iscrizione={cfg.get('token')}" if base_url else ""


def render_modulo_iscrizione_nativo(token):
    """Modulo pubblico interno: crea una scheda in attesa senza Google Forms/Sheets."""
    cfg = config_societa.get("modulo_iscrizione_nativo", {})
    token_atteso = str(cfg.get("token", "")) if isinstance(cfg, dict) else ""
    if (
        not isinstance(cfg, dict)
        or not cfg.get("attivo", False)
        or not token_atteso
        or not hmac.compare_digest(token_atteso, str(token or ""))
    ):
        st.error("Questo modulo di iscrizione non è attivo oppure il collegamento non è valido.")
        return

    stagione_modulo = str(cfg.get("stagione", "") or "").strip()
    if not stagione_modulo:
        stagioni_cfg = [str(x).strip() for x in config_societa.get("stagioni_gestite", []) if str(x).strip()]
        stagione_modulo = stagioni_cfg[0] if stagioni_cfg else "2026/2027"
    gruppi_modulo = []
    for voce in st.session_state.get("gruppi_societa", []):
        gruppo_norm = normalizza_nome_gruppo(voce)
        if gruppo_norm and gruppo_norm.casefold() not in {x.casefold() for x in gruppi_modulo}:
            gruppi_modulo.append(gruppo_norm)
    gruppi_modulo.sort(key=str.casefold)
    if not gruppi_modulo:
        st.error("La società non ha ancora configurato i gruppi disponibili per l'iscrizione.")
        return

    logo = logo_societa_path()
    if logo:
        _, col_logo, _ = st.columns([2, 1, 2])
        col_logo.image(logo, use_container_width=True)
    st.markdown(f"<h1 style='text-align:center;color:{config_societa.get('colore_primario','#0b5fa5')};'>🏐 ISCRIZIONE {nome_societa.upper()}</h1>", unsafe_allow_html=True)
    st.markdown(f"<p style='text-align:center;'>Stagione sportiva <b>{stagione_modulo}</b></p>", unsafe_allow_html=True)
    st.info("La richiesta sarà controllata dalla segreteria prima dell'attivazione definitiva dell'anagrafica.")

    with st.form("modulo_iscrizione_nativo_pubblico", clear_on_submit=False):
        st.markdown("### Dati atleta")
        c1, c2 = st.columns(2)
        cognome = c1.text_input("Cognome atleta *")
        nome = c2.text_input("Nome atleta *")
        c3, c4 = st.columns(2)
        sesso = c3.selectbox("Genere *", ["F", "M", "ALTRO / NON INDICATO"])
        cf = c4.text_input("Codice fiscale", max_chars=16)
        c5, c6, c7 = st.columns([1.1, 1.4, .8])
        data_nas = c5.text_input("Data di nascita *", placeholder="GG/MM/AAAA")
        luogo_nas = c6.text_input("Luogo di nascita")
        prov_nas = c7.text_input("Provincia nascita", max_chars=2)

        st.markdown("### Residenza e gruppo")
        r1, r2, r3 = st.columns([1.7, 1.1, .7])
        indirizzo = r1.text_input("Indirizzo")
        citta = r2.text_input("Città")
        provincia = r3.text_input("Provincia", max_chars=2)
        gruppo = st.selectbox("Gruppo / squadra richiesta *", gruppi_modulo)
        scuola = st.text_input("Scuola frequentata (per Scuola/Minivolley)")
        classe = st.text_input("Classe frequentata")
        scad_visita = st.text_input("Scadenza visita medica", placeholder="GG/MM/AAAA")

        st.markdown("### Contatti genitori o atleta maggiorenne")
        g1, g2 = st.columns(2)
        gen1 = g1.text_input("Nome e cognome referente 1 *")
        tel1 = g1.text_input("Telefono referente 1 *")
        mail1 = g1.text_input("Email referente 1 *")
        gen2 = g2.text_input("Nome e cognome referente 2")
        tel2 = g2.text_input("Telefono referente 2")
        mail2 = g2.text_input("Email referente 2")
        note_iscrizione = st.text_area("Note per la segreteria")
        privacy = st.checkbox(
            "Confermo di aver letto l'informativa privacy e autorizzo il trattamento dei dati per la gestione dell'iscrizione. *"
        )
        invia = st.form_submit_button("INVIA RICHIESTA DI ISCRIZIONE", type="primary", use_container_width=True)

    if not invia:
        return

    def data_valida_o_vuota(valore, obbligatoria=False):
        testo = str(valore or "").strip()
        if not testo:
            return not obbligatoria
        try:
            datetime.strptime(testo, "%d/%m/%Y")
            return True
        except ValueError:
            return False

    errori = []
    if not cognome.strip() or not nome.strip(): errori.append("Inserisci nome e cognome dell'atleta.")
    if not data_valida_o_vuota(data_nas, obbligatoria=True): errori.append("Inserisci una data di nascita valida nel formato GG/MM/AAAA.")
    if scad_visita.strip() and not data_valida_o_vuota(scad_visita): errori.append("La scadenza della visita medica non è valida.")
    if len(gen1.strip()) < 3 or len(tel1.strip()) < 6: errori.append("Inserisci referente e telefono principale.")
    if not _safe_email(mail1): errori.append("Inserisci un indirizzo email principale valido.")
    if mail2.strip() and not _safe_email(mail2): errori.append("L'indirizzo email del secondo referente non è valido.")
    if not privacy: errori.append("È necessario confermare l'informativa privacy.")
    if errori:
        for errore in errori: st.error(errore)
        return

    atlete = carica_atlete()
    cf_norm = re.sub(r"[^A-Z0-9]", "", cf.upper())
    identita = lambda v: re.sub(r"[^a-z0-9]", "", unicodedata.normalize("NFKD", str(v or "")).casefold())
    duplicata = any(
        str(a.get("stagione", "")) == stagione_modulo
        and (
            (cf_norm and re.sub(r"[^A-Z0-9]", "", str(a.get("cf", "")).upper()) == cf_norm)
            or (
                identita(a.get("cognome")) == identita(cognome)
                and identita(a.get("nome")) == identita(nome)
                and re.sub(r"\D", "", str(a.get("data_nas", ""))) == re.sub(r"\D", "", data_nas)
            )
        )
        for a in atlete if a.get("cognome") != "--- Inizializzazione"
    )
    if duplicata:
        st.warning("Esiste già una richiesta o un'anagrafica con questi dati. Contatta la segreteria per eventuali correzioni.")
        return

    gruppo_norm = normalizza_nome_gruppo(gruppo)
    nuova = crea_scheda_standard({
        "cognome": cognome.strip().upper(), "nome": nome.strip().upper(),
        "sesso": "N" if sesso == "ALTRO / NON INDICATO" else sesso,
        "cf": cf_norm, "data_nas": data_nas.strip(), "luogo_nas": luogo_nas.strip(),
        "prov_nas": prov_nas.strip().upper(), "indirizzo_res": indirizzo.strip(),
        "citta_res": citta.strip(), "prov_res": provincia.strip().upper(),
        "gruppo": gruppo_norm, "categoria": categoria_da_gruppo(gruppo_norm),
        "scuola_frequentata": scuola.strip(), "classe_scolastica": classe.strip(),
        "scad_visita": scad_visita.strip(), "gen1": gen1.strip(), "tel1": tel1.strip(),
        "mail1": _safe_email(mail1), "gen2": gen2.strip(), "tel2": tel2.strip(),
        "mail2": _safe_email(mail2), "stato": "In attesa",
    }, stagione_attiva=stagione_modulo)
    nuova.update({
        "sync_key": f"NATIVO-{uuid.uuid4().hex}", "origine_iscrizione": "MODULO NATIVO",
        "richiesta_iscrizione": True, "richiesta_inviata_il": ora_italiana().isoformat(timespec="seconds"),
        "note_iscrizione": note_iscrizione.strip(), "privacy_richiesta_accettata": True,
    })
    atlete.append(nuova)
    salva_atlete(atlete)
    st.session_state["elenco_atlete"] = atlete
    st.success("Richiesta inviata correttamente. La segreteria procederà alla verifica dei dati.")
    st.balloons()


