# ============================================================
# CALENDARIO PUBBLICO PRIVATO PER GRUPPI / SQUADRE
# ============================================================
def _calpub_norm(v):
    return ' '.join(str(v or '').strip().casefold().split())

def _calpub_data(v):
    for fmt in ('%d/%m/%Y','%Y-%m-%d','%d-%m-%Y'):
        try: return datetime.strptime(str(v or '').strip(), fmt).date()
        except Exception: pass
    return None

def _calpub_eventi(stagione, gruppi, tipi=None, includi_comunicazioni=True):
    gruppi_norm = {_calpub_norm(x) for x in (gruppi or []) if str(x).strip()}
    tipi = {str(x).strip().upper() for x in (tipi or ['ALLENAMENTO','GARA','COMUNICAZIONE'])}
    eventi = []
    allen_db = carica_json(FILE_ALLENAMENTI, {}) or {}
    gare_db = carica_json(FILE_GARE, {}) or {}
    manuali_db = carica_json(FILE_EVENTI_CALENDARIO, {}) or {}
    for x in allen_db.get(str(stagione), []) or []:
        gruppo = str(x.get('squadra','')).strip(); data_ev = _calpub_data(x.get('data'))
        if not data_ev or _calpub_norm(gruppo) not in gruppi_norm or 'ALLENAMENTO' not in tipi: continue
        eventi.append({'data':data_ev,'inizio':str(x.get('ora_inizio','')).strip(),'fine':str(x.get('ora_fine','')).strip(),
                       'tipo':'ALLENAMENTO','gruppo':gruppo,'titolo':f'Allenamento — {gruppo}',
                       'luogo':str(x.get('palestra','')).strip(),'note':str(x.get('note','')).strip(),
                       'annullato':bool(x.get('non_svolto'))})
    for x in gare_db.get(str(stagione), []) or []:
        gruppo = str(x.get('squadra','')).strip(); data_ev = _calpub_data(x.get('data'))
        if not data_ev or _calpub_norm(gruppo) not in gruppi_norm or 'GARA' not in tipi: continue
        avv = str(x.get('avversaria','') or 'avversaria da definire').strip()
        note = ' · '.join(v for v in [f"Ritrovo {x.get('ora_ritrovo','')}" if x.get('ora_ritrovo') else '', str(x.get('note','')).strip()] if v)
        eventi.append({'data':data_ev,'inizio':str(x.get('ora','')).strip(),'fine':'','tipo':'GARA','gruppo':gruppo,
                       'titolo':f'{gruppo} — Gara contro {avv}','luogo':str(x.get('campo','')).strip(),'note':note,'annullato':False})
    if includi_comunicazioni:
        for x in manuali_db.get(str(stagione), []) or []:
            gruppo = str(x.get('gruppo','') or 'TUTTI').strip(); data_ev = _calpub_data(x.get('data'))
            visibile = _calpub_norm(gruppo) in gruppi_norm or _calpub_norm(gruppo) == 'tutti'
            if not data_ev or not visibile or 'COMUNICAZIONE' not in tipi: continue
            eventi.append({'data':data_ev,'inizio':str(x.get('ora_inizio','')).strip(),'fine':str(x.get('ora_fine','')).strip(),
                           'tipo':str(x.get('tipo','COMUNICAZIONE')).upper(),'gruppo':gruppo,
                           'titolo':str(x.get('titolo','Comunicazione')).strip(),'luogo':str(x.get('luogo','')).strip(),
                           'note':str(x.get('note','')).strip(),'annullato':False})
    return sorted(eventi, key=lambda e:(e['data'],e.get('inizio',''),e.get('titolo','')))

def _calpub_ics(eventi, nome_calendario):
    def esc(v):
        return str(v or '').replace('\\','\\\\').replace(';','\\;').replace(',','\\,').replace('\n','\\n')
    righe=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Monviso Volley//Calendario condiviso//IT',
           f'X-WR-CALNAME:{esc(nome_calendario)}','CALSCALE:GREGORIAN','METHOD:PUBLISH']
    for ev in eventi:
        data_ev=ev['data']; ora=str(ev.get('inizio','')).strip()
        try: hh,mm=[int(x) for x in ora.split(':')[:2]]; inizio=datetime.combine(data_ev,datetime.min.time().replace(hour=hh,minute=mm)); dtstart=inizio.strftime('%Y%m%dT%H%M%S')
        except Exception: dtstart=data_ev.strftime('%Y%m%d')
        fine=str(ev.get('fine','')).strip()
        try: hh,mm=[int(x) for x in fine.split(':')[:2]]; dtend=datetime.combine(data_ev,datetime.min.time().replace(hour=hh,minute=mm)).strftime('%Y%m%dT%H%M%S')
        except Exception:
            dtend=(data_ev+timedelta(days=1)).strftime('%Y%m%d') if len(dtstart)==8 else (datetime.strptime(dtstart,'%Y%m%dT%H%M%S')+timedelta(hours=2)).strftime('%Y%m%dT%H%M%S')
        suff=';VALUE=DATE' if len(dtstart)==8 else ''
        righe += ['BEGIN:VEVENT',f'UID:{uuid.uuid5(uuid.NAMESPACE_URL, str(ev))}@monvisovolley',
                  f'DTSTAMP:{datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")}',f'DTSTART{suff}:{dtstart}',f'DTEND{suff}:{dtend}',
                  f'SUMMARY:{esc(ev.get("titolo",""))}',f'LOCATION:{esc(ev.get("luogo",""))}',
                  f'DESCRIPTION:{esc(ev.get("note",""))}','END:VEVENT']
    righe.append('END:VCALENDAR')
    return ('\r\n'.join(righe)+'\r\n').encode('utf-8')

def render_calendario_pubblico(token):
    cfg_all = (config_societa.get('calendari_pubblici', []) or [])
    cfg = next((x for x in cfg_all if hmac.compare_digest(str(x.get('token','')), str(token or ''))), None)
    if not cfg or not cfg.get('attivo', True):
        st.error('Collegamento non valido o disattivato.'); return
    scadenza = _calpub_data(cfg.get('scade_il',''))
    if scadenza and ora_italiana().date() > scadenza:
        st.error('Questo collegamento è scaduto. Richiedi un nuovo link alla società.'); return
    stagione=str(cfg.get('stagione','')).strip(); gruppi=list(cfg.get('gruppi',[]) or [])
    eventi=_calpub_eventi(stagione,gruppi,cfg.get('tipi'),bool(cfg.get('includi_comunicazioni',True)))
    oggi=ora_italiana().date(); mese_default=oggi.month; anno_default=oggi.year
    st.markdown(f"<h1 style='text-align:center;color:#0b5fa5'>🏐 {html.escape(nome_societa)}</h1>",unsafe_allow_html=True)
    st.markdown(f"<h2 style='text-align:center'>📅 {' · '.join(html.escape(x) for x in gruppi)}</h2>",unsafe_allow_html=True)
    st.caption(f'Stagione {stagione} · Calendario in sola lettura aggiornato dal gestionale')
    cp1,cp2=st.columns(2)
    anno=int(cp1.number_input('Anno',min_value=2020,max_value=2100,value=anno_default,step=1,key='calpub_anno'))
