    mese_eventi=[e for e in eventi if e['data'].year==anno and e['data'].month==mese]
    per_data={}
    for e in mese_eventi: per_data.setdefault(e['data'],[]).append(e)
    intest=''.join(f'<div class="cph">{x}</div>' for x in ['Lun','Mar','Mer','Gio','Ven','Sab','Dom'])
