def _cal_data(value):
    """Converte le date del gestionale in date Python senza interrompere la pagina."""
    testo = str(value or "").strip()
    for formato in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
        try:
            return datetime.strptime(testo, formato).date()
        except Exception:
            pass
    return None


def _cal_ora(value, default="00:00"):
    testo = str(value or "").strip().replace(".", ":")
    match = re.search(r"(\d{1,2}):(\d{2})", testo)
    if not match:
        return default
    ore, minuti = int(match.group(1)), int(match.group(2))
    if 0 <= ore <= 23 and 0 <= minuti <= 59:
        return f"{ore:02d}:{minuti:02d}"
    return default


def _cal_colore(gruppo, colori=None):
    colori = colori or {}
    chiave = _presenze_testo_normale(gruppo)
    if chiave in colori:
        return str(colori[chiave])
    palette = ["#2563EB", "#DC2626", "#16A34A", "#9333EA", "#EA580C", "#0891B2", "#DB2777", "#65A30D", "#4F46E5", "#CA8A04"]
    return palette[int(hashlib.md5(chiave.encode("utf-8")).hexdigest()[:8], 16) % len(palette)] if chiave else "#64748B"


def _cal_data_appartiene_stagione(data_evento, stagione):
    """Evita che eventi archiviati sotto la chiave errata passino a un'altra stagione."""
    if not isinstance(data_evento, date):
        return False
    match = re.fullmatch(r"\s*(\d{4})\s*/\s*(\d{4})\s*", str(stagione or ""))
    if not match:
        return True
    anno_inizio, anno_fine = int(match.group(1)), int(match.group(2))
    if anno_fine != anno_inizio + 1:
        return True
    return date(anno_inizio, 7, 1) <= data_evento <= date(anno_fine, 6, 30)


def _cal_squadra_disattivata(stagione, nome_squadra="", squadra_id=""):
    """Esclude dal calendario solo una squadra trovata e marcata esplicitamente inattiva."""
    nome_norm = _presenze_testo_normale(nome_squadra)
    nome_alias = _presenze_testo_normale(normalizza_nome_gruppo(nome_squadra))
    chiavi_evento = {x for x in (nome_norm, nome_alias) if x}
    id_norm = str(squadra_id or "").strip()
    squadre = (st.session_state.get("squadre_campionati", {}) or {}).get(stagione, []) or []
    for squadra in squadre:
        stessa_id = bool(id_norm and str(squadra.get("id", "")).strip() == id_norm)
        chiavi_record = set()
        for valore_record in (squadra.get("nome", ""), squadra.get("gruppo", "")):
            chiavi_record.add(_presenze_testo_normale(valore_record))
            chiavi_record.add(_presenze_testo_normale(normalizza_nome_gruppo(valore_record)))
        chiavi_record.discard("")
        stesso_nome = bool(chiavi_evento & chiavi_record)
        if stessa_id or stesso_nome:
            return not bool(squadra.get("attiva", True))
    return False


def _cal_eventi_unificati(stagione):
    """Unisce allenamenti, gare ed eventi manuali mantenendo la fonte originale."""
    colori = (config_societa.get("colori_gruppi_squadre", {}) or {}).get(stagione, {}) or {}
    eventi = []
    for seduta in (st.session_state.get("allenamenti_tecnici", {}) or {}).get(stagione, []) or []:
        data_evento = _cal_data(seduta.get("data"))
        if not data_evento or not _cal_data_appartiene_stagione(data_evento, stagione):
            continue
        gruppo = str(seduta.get("squadra", "") or "Senza gruppo").strip()
        if _cal_squadra_disattivata(stagione, gruppo, seduta.get("squadra_id", "")):
            continue
        eventi.append({
            "id": f"allenamento:{seduta.get('id','')}", "origine": "ALLENAMENTO",
            "data": data_evento, "inizio": _cal_ora(seduta.get("ora_inizio"), "00:00"),
            "fine": _cal_ora(seduta.get("ora_fine"), ""), "gruppo": gruppo,
            "titolo": f"{seduta.get('tipo','Allenamento')} — {gruppo}",
            "luogo": str(seduta.get("palestra", "")), "note": str(seduta.get("note", "")),
            "colore": _cal_colore(gruppo, colori),
            "stato": "NON SVOLTO" if seduta.get("non_svolto") else "PROGRAMMATO",
        })
    for gara in (st.session_state.get("calendario_gare", {}) or {}).get(stagione, []) or []:
        data_evento = _cal_data(gara.get("data"))
        if not data_evento or not _cal_data_appartiene_stagione(data_evento, stagione):
            continue
        gruppo = str(gara.get("squadra", "") or "Senza squadra").strip()
        if _cal_squadra_disattivata(stagione, gruppo, gara.get("squadra_id", "")):
            continue
        avversaria = str(gara.get("avversaria", "") or "Avversaria da definire").strip()
        eventi.append({
            "id": f"gara:{gara.get('id','')}", "origine": "GARA", "data": data_evento,
            "inizio": _cal_ora(gara.get("ora"), "00:00"), "fine": "", "gruppo": gruppo,
            "titolo": f"{gruppo} — Gara contro {avversaria}",
            "luogo": str(gara.get("campo", "")),
            "note": " · ".join(x for x in [f"Ritrovo {gara.get('ora_ritrovo','')}" if gara.get("ora_ritrovo") else "", str(gara.get("note", ""))] if x),
            "colore": _cal_colore(gruppo, colori), "stato": "PROGRAMMATO",
        })
    for evento in (st.session_state.get("eventi_calendario_manuali", {}) or {}).get(stagione, []) or []:
        data_evento = _cal_data(evento.get("data"))
        if not data_evento or not _cal_data_appartiene_stagione(data_evento, stagione):
            continue
        gruppo = str(evento.get("gruppo", "") or "TUTTI").strip()
        eventi.append({
            "id": f"manuale:{evento.get('id','')}", "origine": str(evento.get("tipo", "EVENTO")).upper(),
            "data": data_evento, "inizio": _cal_ora(evento.get("ora_inizio"), "00:00"),
            "fine": _cal_ora(evento.get("ora_fine"), ""), "gruppo": gruppo,
            "titolo": str(evento.get("titolo", "Evento")), "luogo": str(evento.get("luogo", "")),
            "note": str(evento.get("note", "")), "colore": str(evento.get("colore", "")) or _cal_colore(gruppo, colori),
            "stato": "PROGRAMMATO",
        })
    return sorted(eventi, key=lambda x: (x["data"], x.get("inizio", ""), x.get("titolo", "")))


def _cal_stile_evento(colore):
    """Sfondo pieno con testo automaticamente leggibile."""
    colore = str(colore or '#2563EB').strip()
    if not re.fullmatch(r'#[0-9A-Fa-f]{6}', colore):
        colore = '#2563EB'
    r, g, b = int(colore[1:3],16), int(colore[3:5],16), int(colore[5:7],16)
    luminanza = (0.299*r + 0.587*g + 0.114*b)
    testo = '#10233f' if luminanza >= 165 else '#ffffff'
    return f'background:{colore};border-left-color:{colore};color:{testo};box-shadow:inset 0 0 0 1px rgba(0,0,0,.10)'


def _cal_html_mese(eventi, anno, mese):
    nomi_mesi = ["", "Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno", "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"]
    per_data = {}
    for evento in eventi:
        per_data.setdefault(evento["data"], []).append(evento)
    settimane = pycalendar.Calendar(firstweekday=0).monthdatescalendar(anno, mese)
    celle = []
    oggi = ora_italiana().date()
    for settimana in settimane:
        for giorno in settimana:
            classi = "cal-day"
            if giorno.month != mese: classi += " cal-other"
            if giorno == oggi: classi += " cal-today"
            contenuto = [f'<div class="cal-num">{giorno.day}</div>']
            for evento in per_data.get(giorno, [])[:5]:
                titolo = str(evento.get("titolo", "")).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
                orario = evento.get("inizio", "") if evento.get("inizio") != "00:00" else ""
                contenuto.append(f'<div class="cal-event" title="{titolo}" style="{_cal_stile_evento(evento.get("colore", "#2563EB"))}"><b>{orario}</b> {titolo}</div>')
            if len(per_data.get(giorno, [])) > 5:
                contenuto.append(f'<div class="cal-more">+{len(per_data[giorno])-5} altri</div>')
            celle.append(f'<div class="{classi}">{"".join(contenuto)}</div>')
    intestazioni = "".join(f'<div class="cal-head">{x}</div>' for x in ["Lun", "Mar", "Mer", "Gio", "Ven", "Sab", "Dom"])
    return f'''<style>
    .cal-wrap{{font-family:Arial,sans-serif;border:1px solid #dbe3ee;border-radius:12px;overflow:hidden;background:white}}
    .cal-title{{font-size:22px;font-weight:700;text-align:center;padding:14px;color:#0b5fa5;background:#f8fafc}}
    .cal-grid{{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}}
    .cal-head{{padding:9px;text-align:center;font-weight:700;background:#0b5fa5;color:white;border-right:1px solid #dbe3ee}}
    .cal-day{{min-height:116px;padding:6px;border-right:1px solid #e5e7eb;border-top:1px solid #e5e7eb;overflow:hidden}}
    .cal-other{{background:#f8fafc;color:#9ca3af}} .cal-today{{background:#fff7d6;box-shadow:inset 0 0 0 2px #f59e0b}}
    .cal-num{{font-weight:700;margin-bottom:4px}} .cal-event{{font-size:11px;line-height:1.25;margin:3px 0;padding:4px;background:#f1f5f9;border-left:5px solid #2563EB;border-radius:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#172033}}
    .cal-more{{font-size:11px;color:#0b5fa5;font-weight:700;margin-top:4px}}
    @media(max-width:900px){{.cal-day{{min-height:86px;padding:3px}}.cal-event{{font-size:9px;padding:2px}}.cal-head{{font-size:11px}}}}
    </style><div class="cal-wrap"><div class="cal-title">{nomi_mesi[mese]} {anno}</div><div class="cal-grid">{intestazioni}{''.join(celle)}</div></div>'''


def _cal_html_settimana(eventi, lunedi):
    """Vista settimanale compatta con sette riquadri in stile calendario."""
    nomi_giorni = ["Lunedì", "Martedì", "Mercoledì", "Giovedì", "Venerdì", "Sabato", "Domenica"]
    oggi = ora_italiana().date(); riquadri = []
    for indice in range(7):
        giorno = lunedi + timedelta(days=indice)
        classi = "week-card" + (" week-today" if giorno == oggi else "")
        eventi_giorno = [x for x in eventi if x.get("data") == giorno]
        elementi = []
        for evento in eventi_giorno:
            titolo = str(evento.get("titolo", "")).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
            luogo = str(evento.get("luogo", "") or "Luogo da definire").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            orario = evento.get("inizio", "") if evento.get("inizio") != "00:00" else ""
            elementi.append(f'<div class="week-event" style="{_cal_stile_evento(evento.get("colore", "#2563EB"))}" title="{titolo}"><b>{orario}</b><span>{titolo}</span><small>{luogo}</small></div>')
        vuoto = '<div class="week-empty">Nessun evento</div>' if not elementi else ""
        riquadri.append(f'<div class="{classi}"><div class="week-name">{nomi_giorni[indice]}</div><div class="week-date">{giorno.strftime("%d/%m")}</div>{"".join(elementi)}{vuoto}</div>')
    domenica = lunedi + timedelta(days=6)
    return f'''<style>
    .week-wrap{{font-family:Arial,sans-serif;border:1px solid #dbe3ee;border-radius:12px;overflow:hidden;background:white}}
    .week-title{{font-size:18px;font-weight:700;text-align:center;padding:12px;color:#0b5fa5;background:#eef6ff}}
    .week-grid{{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:0}}
    .week-card{{min-height:230px;padding:9px;border-top:1px solid #dbe3ee;border-right:1px solid #dbe3ee;background:#fff;overflow:hidden}}
    .week-card:last-child{{border-right:0}} .week-today{{background:#fff7d6;box-shadow:inset 0 0 0 2px #f59e0b}}
    .week-name{{font-weight:700;color:#183b5b;text-align:center;font-size:13px}} .week-date{{font-size:20px;font-weight:800;text-align:center;color:#0b5fa5;margin:4px 0 10px}}
    .week-event{{font-size:11px;line-height:1.25;margin:6px 0;padding:6px;background:#f1f5f9;border-left:6px solid #2563EB;border-radius:5px;overflow:hidden}}
    .week-event b,.week-event span,.week-event small{{display:block}} .week-event span{{font-weight:700;margin-top:2px}} .week-event small{{color:inherit;opacity:.88;margin-top:4px}}
    .week-empty{{font-size:11px;text-align:center;color:#94a3b8;padding-top:35px}}
    @media(max-width:950px){{.week-grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}.week-card{{min-height:170px;border-bottom:1px solid #dbe3ee}}}}
    @media(max-width:560px){{.week-grid{{grid-template-columns:1fr}}.week-card{{min-height:120px}}}}
    </style><div class="week-wrap"><div class="week-title">Settimana dal {lunedi.strftime("%d/%m/%Y")} al {domenica.strftime("%d/%m/%Y")}</div><div class="week-grid">{"".join(riquadri)}</div></div>'''


def _cal_excel(eventi):
    righe = [{"Data":x["data"].strftime("%d/%m/%Y"), "Inizio":x.get("inizio",""), "Fine":x.get("fine",""), "Tipo":x.get("origine",""), "Gruppo / squadra":x.get("gruppo",""), "Evento":x.get("titolo",""), "Luogo":x.get("luogo",""), "Stato":x.get("stato",""), "Note":x.get("note","")} for x in eventi]
    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        pd.DataFrame(righe).to_excel(writer, index=False, sheet_name="Calendario")
        ws = writer.book["Calendario"]
        ws.freeze_panes = "A2"; ws.auto_filter.ref = ws.dimensions
        for col in ws.columns:
            ws.column_dimensions[col[0].column_letter].width = min(max(len(str(c.value or "")) for c in col) + 2, 55)
    return buffer.getvalue()


def _cal_pdf(eventi, titolo):
    buffer = io.BytesIO(); doc = SimpleDocTemplate(buffer, pagesize=landscape(A4), rightMargin=24, leftMargin=24, topMargin=28, bottomMargin=24)
    styles = getSampleStyleSheet(); elementi = [Paragraph(titolo, styles["Title"]), Spacer(1, 10)]
    dati = [["Data", "Ora", "Tipo", "Gruppo", "Evento", "Luogo"]]
    for x in eventi:
        dati.append([x["data"].strftime("%d/%m/%Y"), x.get("inizio", ""), x.get("origine", ""), x.get("gruppo", ""), x.get("titolo", ""), x.get("luogo", "")])
    tabella = Table(dati, repeatRows=1, colWidths=[58,42,65,90,245,130])
    tabella.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#0B5FA5")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),7),("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAFC")])]))
    elementi.append(tabella); doc.build(elementi); return buffer.getvalue()


def _google_calendar_service():
    """Usa OAuth Calendar; in alternativa un service account con calendario condiviso."""
    errori = []
    for nome_sezione in ("gcp_calendar_oauth", "gcp_drive_oauth"):
        try:
            sezione = st.secrets.get(nome_sezione)
            if not sezione: continue
            cfg = dict(sezione); raw = cfg.get("content", "")
            if raw:
                cfg = {**(json.loads(raw) if isinstance(raw, str) else dict(raw)), **{k:v for k,v in cfg.items() if k != "content"}}
            from google.oauth2.credentials import Credentials
            from google.auth.transport.requests import Request
            from googleapiclient.discovery import build
            creds = Credentials(token=None, refresh_token=str(cfg.get("refresh_token", "")), token_uri=str(cfg.get("token_uri", "https://oauth2.googleapis.com/token")), client_id=str(cfg.get("client_id", "")), client_secret=str(cfg.get("client_secret", "")), scopes=["https://www.googleapis.com/auth/calendar"])
            if not creds.refresh_token or not creds.client_id or not creds.client_secret: continue
            creds.refresh(Request())
            return build("calendar", "v3", credentials=creds, cache_discovery=False), ""
        except Exception as exc:
            errori.append(f"{nome_sezione}: {type(exc).__name__}: {exc}")
    try:
        sezione = st.secrets.get("gcp_backup_service_account")
        raw = sezione.get("content", "") if sezione else ""
        if raw:
            from google.oauth2 import service_account
            from googleapiclient.discovery import build
            info = json.loads(raw) if isinstance(raw, str) else dict(raw)
            creds = service_account.Credentials.from_service_account_info(info, scopes=["https://www.googleapis.com/auth/calendar"])
            return build("calendar", "v3", credentials=creds, cache_discovery=False), ""
    except Exception as exc:
        errori.append(f"service account: {type(exc).__name__}: {exc}")
    return None, " | ".join(errori) or "Credenziali Google Calendar non configurate."


def _cal_sync_google(eventi, stagione, calendar_id):
    servizio, errore = _google_calendar_service()
    if servizio is None: return {"ok":False, "error":errore, "creati":0, "aggiornati":0}
    mappa_root = config_societa.setdefault("google_calendar_eventi", {}).setdefault(stagione, {})
    hash_root = config_societa.setdefault("google_calendar_hash", {}).setdefault(stagione, {})
    colori_gruppi = (config_societa.get("google_calendar", {}).get("colori_gruppi", {}).get(stagione, {}) or {})
    creati = aggiornati = invariati = 0; errori = []
    for evento in eventi:
        chiave = str(evento.get("id", "")); inizio = datetime.combine(evento["data"], datetime.strptime(evento.get("inizio") or "00:00", "%H:%M").time(), tzinfo=ROME_TZ)
        fine_testo = evento.get("fine") or ""
        fine = datetime.combine(evento["data"], datetime.strptime(fine_testo, "%H:%M").time(), tzinfo=ROME_TZ) if fine_testo else inizio + timedelta(hours=2)
        if fine <= inizio: fine = inizio + timedelta(hours=2)
        body = {"summary":evento.get("titolo","Evento"), "location":evento.get("luogo",""), "description":f"Origine: {evento.get('origine','')}\nGruppo: {evento.get('gruppo','')}\n{evento.get('note','')}", "start":{"dateTime":inizio.isoformat(),"timeZone":"Europe/Rome"}, "end":{"dateTime":fine.isoformat(),"timeZone":"Europe/Rome"}, "extendedProperties":{"private":{"gestionale_id":chiave,"stagione":stagione}}}
        color_id = str(colori_gruppi.get(str(evento.get('gruppo','')).strip(), '') or '').strip()
        if color_id:
            body['colorId'] = color_id
        firma_evento = hashlib.sha256(json.dumps(body, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
        try:
            google_id = str(mappa_root.get(chiave, ""))
            if google_id and hash_root.get(chiave) == firma_evento:
                invariati += 1
                continue
            operazione = (lambda: servizio.events().update(calendarId=calendar_id, eventId=google_id, body=body).execute()) if google_id else (lambda: servizio.events().insert(calendarId=calendar_id, body=body).execute())
            risposta = None
            for tentativo in range(4):
                try:
                    risposta = operazione()
                    break
                except Exception as exc_retry:
                    testo_retry = str(exc_retry).casefold()
                    if ("ratelimitexceeded" not in testo_retry and "rate limit exceeded" not in testo_retry and "429" not in testo_retry) or tentativo == 3:
                        raise
                    time.sleep(2 ** (tentativo + 1))
            if google_id:
                aggiornati += 1
            else:
                mappa_root[chiave] = (risposta or {}).get("id", "")
                creati += 1
            hash_root[chiave] = firma_evento
            time.sleep(0.20)
        except Exception as exc:
            dettaglio_errore = f"{type(exc).__name__}: {exc}"
            dettaglio_minuscolo = dettaglio_errore.casefold()
            if "accessnotconfigured" in dettaglio_minuscolo or "has not been used" in dettaglio_minuscolo or "calendar api" in dettaglio_minuscolo and "disabled" in dettaglio_minuscolo:
                dettaglio_errore = "La Google Calendar API non è abilitata nel progetto Google collegato al gestionale. Abilitala in Google Cloud e riprova dopo alcuni minuti."
            elif "insufficient" in dettaglio_minuscolo or "insufficient permission" in dettaglio_minuscolo or "insufficient authentication scopes" in dettaglio_minuscolo:
                dettaglio_errore = "Il token Google non dispone del permesso Calendar. Occorre rigenerare l’autorizzazione OAuth includendo Google Calendar."
            elif "not found" in dettaglio_minuscolo or "404" in dettaglio_minuscolo:
                dettaglio_errore = "Calendario Google non trovato. Controlla l’ID oppure condividi il calendario con l’account configurato nel gestionale."
            elif "ratelimitexceeded" in dettaglio_minuscolo or "rate limit exceeded" in dettaglio_minuscolo or "429" in dettaglio_minuscolo:
                dettaglio_errore = "Google ha temporaneamente limitato le richieste. La sincronizzazione automatica è sospesa per 10 minuti; riprova dopo l’attesa."
                config_societa.setdefault("google_calendar", {})["pausa_fino"] = (ora_italiana() + timedelta(minutes=10)).isoformat(timespec="seconds")
            errori.append(f"{evento.get('titolo','Evento')}: {dettaglio_errore}")
            if "temporaneamente limitato" in dettaglio_errore:
                break
    salva_json_sicuro(FILE_CONFIG_SOCIETA, config_societa)
    return {"ok":not errori, "creati":creati, "aggiornati":aggiornati, "invariati":invariati, "errori":errori, "error":errori[0] if errori else ""}
