# FEEDBACK SEMANTICO / SINCRONIZZAZIONE
# ============================================================
def mostra_esito_sincronizzazione(res, contesto=""):
    """Messaggio semantico: verde=movimenti positivi, azzurro=nessuna modifica, rosso=errore."""
    if not res:
        return
    prefisso = f"{contesto}: " if contesto else ""
    if not res.get("ok"):
        st.markdown(f'<div class="semantic-danger">❌ {prefisso}{res.get("error", "Errore durante la sincronizzazione")}</div>', unsafe_allow_html=True)
        return
    nuove = int(res.get("nuove", 0) or 0)
    aggiornate = int(res.get("aggiornate", 0) or 0)
    invariate = int(res.get("invariate", 0) or 0)
    saltate = int(res.get("saltate", 0) or 0)
    ignorate_eliminate = int(res.get("ignorate_eliminate", 0) or 0)
    if nuove > 0 or aggiornate > 0:
        testo = f"✅ {prefisso}Sincronizzazione effettuata con successo · {nuove} nuove · {aggiornate} aggiornate · {invariate} invariate"
        if ignorate_eliminate:
            testo += f" · {ignorate_eliminate} eliminate ignorate"
        if saltate:
            testo += f" · {saltate} saltate"
        privacy = res.get("privacy", {}) or {}
        if int(privacy.get("inviate", 0) or 0):
            testo += f" · Privacy inviate: {int(privacy.get('inviate', 0) or 0)}"
        if privacy.get("errori"):
            testo += f" · Privacy con errore: {len(privacy.get('errori', []))}"
        st.markdown(f'<div class="semantic-success">{testo}</div>', unsafe_allow_html=True)
    else:
        testo = f"ℹ️ {prefisso}Nessuna atleta da inserire o aggiornare · {invariate} invariate"
        if saltate:
            testo += f" · {saltate} saltate"
        st.markdown(f'<div class="semantic-info">{testo}</div>', unsafe_allow_html=True)
