                rows=[]
                assenze_storico=[]
                at_map_storico = {
                    str(a.get('id','')): a for a in atlete_stagione_attiva
                    if a.get('cognome') != '--- Inizializzazione'
                }
                for x in allen_stagione_visibili:
                    p=x.get('presenze',{}) or {}; stati=[v.get('stato','') if isinstance(v,dict) else str(v) for v in p.values()]
                    rows.append({'Data':x.get('data',''),'Squadra':x.get('squadra',''),'Tipo':x.get('tipo',''),'Orario':f"{x.get('ora_inizio','')} - {x.get('ora_fine','')}".strip(' -'),'Luogo':x.get('palestra',''),'Convocate':len(x.get('convocati_ids',[]) or []),'Presenti':sum(1 for v in stati if v=='Presente'),'Assenti':sum(1 for v in stati if v in {'Assente','Giustificata','Infortunata'})})
                    for aid_storico, presenza_storico in p.items():
                        if not isinstance(presenza_storico, dict):
                            presenza_storico = {'stato': str(presenza_storico or '')}
                        stato_storico = str(presenza_storico.get('stato',''))
                        if stato_storico not in {'Assente','Giustificata','Infortunata'}:
                            continue
                        atleta_storico = at_map_storico.get(str(aid_storico), {})
                        assenze_storico.append({
                            '_allenamento_id': str(x.get('id','')),
                            '_atleta_id': str(aid_storico),
                            'Data': x.get('data',''), 'Squadra': x.get('squadra',''),
                            'Atleta': f"{atleta_storico.get('cognome','')} {atleta_storico.get('nome','')}".strip() or str(aid_storico),
                            'Stato': stato_storico,
                            'Motivazione': presenza_storico.get('motivazione_assenza') or presenza_storico.get('note','') or 'NON COMUNICATA',
                            'Inserita da': presenza_storico.get('motivazione_inserita_da',''),
                            'Inserita il': presenza_storico.get('motivazione_inserita_il',''),
                        })
