                auto_google_cal = st.checkbox('Sincronizza automaticamente quando il calendario cambia', value=bool(cfg_google_cal.get('automatico',False)), key='google_calendar_auto')
                st.markdown('##### Colori delle squadre e dei gruppi su Google Calendar')
