                auto_colori_google_cal = st.checkbox('Assegna automaticamente un colore alle squadre nuove', value=bool(cfg_google_cal.get('colori_automatici',True)), key='google_calendar_auto_colors')
                palette_google_cal = {
                    '1':'Lavanda', '2':'Salvia', '3':'Viola', '4':'Rosa corallo', '5':'Giallo',
                    '6':'Arancione', '7':'Turchese', '8':'Grigio', '9':'Blu', '10':'Verde', '11':'Rosso'
                }
                gruppi_google_cal = sorted({str(x.get('gruppo','')).strip() for x in eventi_completi if str(x.get('gruppo','')).strip()}, key=str.casefold)
                colori_google_stagione = cfg_google_cal.setdefault('colori_gruppi', {}).setdefault(stagione_selezionata, {})
                if auto_colori_google_cal:
                    _ids_google = list(palette_google_cal.keys())
                    _usati_google = {str(v) for v in colori_google_stagione.values() if str(v) in _ids_google}
                    for _gruppo_auto_gc in gruppi_google_cal:
                        if str(colori_google_stagione.get(_gruppo_auto_gc,'')).strip() in _ids_google:
                            continue
                        _libero_gc = next((x for x in _ids_google if x not in _usati_google), None)
                        if _libero_gc is None:
                            _libero_gc = _ids_google[int(hashlib.md5(_gruppo_auto_gc.encode('utf-8')).hexdigest(),16) % len(_ids_google)]
                        colori_google_stagione[_gruppo_auto_gc] = _libero_gc
                        _usati_google.add(_libero_gc)
                scelte_colori_google = {}
                _opzioni_colore_google = ['— PREDEFINITO GOOGLE —'] + [f'{cid} · {nome}' for cid,nome in palette_google_cal.items()]
                for _idx_gc, _gruppo_gc in enumerate(gruppi_google_cal):
                    _salvato_gc = str(colori_google_stagione.get(_gruppo_gc,'') or '')
                    _index_gc = next((i for i,v in enumerate(_opzioni_colore_google) if v.startswith(_salvato_gc + ' ·')), 0) if _salvato_gc else 0
                    _scelta_gc = st.selectbox(_gruppo_gc, _opzioni_colore_google, index=_index_gc, key=f'google_color_{stagione_selezionata}_{_idx_gc}_{hashlib.md5(_gruppo_gc.encode()).hexdigest()[:8]}')
                    scelte_colori_google[_gruppo_gc] = _scelta_gc.split(' · ',1)[0] if ' · ' in _scelta_gc and not _scelta_gc.startswith('—') else ''
                sg1, sg2 = st.columns(2)
                salva_cfg_google_cal = sg1.button('💾 SALVA CONFIGURAZIONE', use_container_width=True, key='google_calendar_save')
                sync_google_cal = sg2.button('🔄 SINCRONIZZA ORA', type='primary', use_container_width=True, disabled=not calendar_id_cal.strip(), key='google_calendar_sync')
                if salva_cfg_google_cal:
                    cfg_google_cal.setdefault('colori_gruppi', {})[stagione_selezionata] = {k:v for k,v in scelte_colori_google.items() if v}
                    cfg_google_cal.update({'calendar_id':calendar_id_cal.strip(),'automatico':auto_google_cal,'colori_automatici':auto_colori_google_cal,'aggiornato_il':ora_italiana().isoformat(timespec='seconds')}); salva_json_sicuro(FILE_CONFIG_SOCIETA, config_societa); imposta_feedback('✅ Configurazione e colori Google Calendar salvati.','success'); st.rerun()
                firma_sync_cal = hashlib.sha256(json.dumps({'eventi':[{**x,'data':x['data'].isoformat()} for x in eventi_completi], 'colori':colori_google_stagione}, ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()
                chiave_firma_sync_cal = f'google_calendar_sync_signature_{stagione_selezionata}'
                pausa_fino_cal = None
                try:
                    pausa_testo_cal = str(cfg_google_cal.get('pausa_fino','')).strip()
                    pausa_fino_cal = datetime.fromisoformat(pausa_testo_cal) if pausa_testo_cal else None
                    if pausa_fino_cal and pausa_fino_cal.tzinfo is None: pausa_fino_cal = pausa_fino_cal.replace(tzinfo=ROME_TZ)
                except Exception:
                    pausa_fino_cal = None
                auto_in_pausa_cal = bool(pausa_fino_cal and ora_italiana() < pausa_fino_cal)
                avvia_auto_sync_cal = bool(auto_google_cal and not auto_in_pausa_cal and calendar_id_cal.strip() and st.session_state.get(chiave_firma_sync_cal) != firma_sync_cal)
                if auto_google_cal and auto_in_pausa_cal:
                    st.info(f"Sincronizzazione automatica in pausa fino alle {pausa_fino_cal.astimezone(ROME_TZ).strftime('%H:%M')} per rispettare i limiti di Google. Il pulsante manuale resta disponibile.")
